// ---------- diepe stamboom, inteelt, bloedpercentage en verwantschap ----------
// Alles wordt berekend uit de stambomen in de database: de stamboom van een paard wordt aangevuld met de
// stambomen van voorouders die zelf een record hebben, zo diep als nodig. Niets hiervan wordt opgeslagen.
const COI_GEN=9;            // inteelt over 9 generaties (zoals HorseTelex en KWPN)
const KIN_GEN=6;            // verwantschap met de populatie: 6 generaties (sneller, voor honderden paren)
const KWPN_COI=5;           // KWPN raadt aan onder 5% inteelt te blijven
const _UNK=new Set(["onbekend","unknown","unbekannt","inconnu","nn","nonamed","unnamed"]);
const pedId=(n)=>{const k=norm(n);return k&&!_UNK.has(k)?k:""};
let _deep={src:null,map:new WeakMap()};
function _deepC(h){if(_deep.src!==state.horses)_deep={src:state.horses,map:new WeakMap()};let c=_deep.map.get(h);if(!c){c={};_deep.map.set(h,c)}return c}
// Posities ("v","mv","vmm",...) -> naam, tot L generaties boven het paard. De eigen stamboom gaat voor;
// lege vakken komen uit de records van voorouders (geslacht moet bij de positie passen).
function deepPed(h,L){if(!h)return{};const c=_deepC(h);if(c[L])return c[L];
  const ped={};const put=(p,n)=>{if(n&&p.length<=L&&!ped[p])ped[p]=String(n)};
  const sb=h.stamboom||{};Object.keys(sb).forEach(k=>{if(/^[vm]+$/.test(k))put(k,sb[k])});
  const self=pedId(h.naam);
  for(let len=1;len<L;len++)Object.keys(ped).forEach(p=>{if(p.length!==len)return;const a=byName(ped[p]);
    if(!a||a===h||!a.stamboom||pedId(a.naam)===self)return;
    if(a.geslacht&&(a.geslacht==="hengst")!==(p.slice(-1)==="v"))return;
    const ab=a.stamboom;Object.keys(ab).forEach(k=>{if(/^[vm]+$/.test(k))put(p+k,ab[k])})});
  return c[L]=ped}
// Per voorouder (genormaliseerde naam) alle posities waarop hij voorkomt; "" is het paard zelf.
function pedIdx(h,L){const c=_deepC(h),k="i"+L;if(c[k])return c[k];const ped=deepPed(h,L),m=new Map();
  const add=(p,n)=>{const id=pedId(n);if(!id)return;let a=m.get(id);if(!a)m.set(id,a=[]);a.push(p)};
  add("",h.naam);Object.keys(ped).forEach(p=>add(p,ped[p]));return c[k]=m}
// Inteeltcoëfficiënt van een (virtueel) veulen van s x m volgens Wright over L generaties:
// F = som over elk pad via een gemeenschappelijke voorouder van (1/2)^(n1+n2+1). Paden die elkaar
// (buiten die voorouder) kruisen, tellen niet mee. De inteelt van de voorouder zelf (1+FA) is weggelaten.
// Per positie de voorouders tussen het paard en die positie (het paard zelf inbegrepen), als ids.
function pedPath(h,L){const c=_deepC(h),k="p"+L;if(c[k])return c[k];const ped=deepPed(h,L),r={"":[]};
  const ids=(p)=>{if(r[p])return r[p];const q=p.slice(0,-1);const up=ids(q);const x=pedId(q?ped[q]:h.naam);return r[p]=x?up.concat(x):up};
  Object.keys(ped).forEach(ids);return c[k]=r}
function coi(s,m,L){L=L||COI_GEN;const R=L-1;const ps=deepPed(s,R),pm=deepPed(m,R),is=pedIdx(s,R),im=pedIdx(m,R),qs=pedPath(s,R),qm=pedPath(m,R);
  let F=0;const common=new Map();const [small,other]=is.size<=im.size?[is,im]:[im,is];
  for(const id of small.keys()){if(!other.has(id))continue;const A=is.get(id),B=im.get(id);
    for(const a of A){const midA=qs[a];
      for(const b of B){const midB=qm[b];let blocked=false;
        if(midA.length&&midB.length)for(const x of midB){if(midA.includes(x)){blocked=true;break}}
        if(blocked)continue;const c=Math.pow(.5,a.length+b.length+1);F+=c;
        let e=common.get(id);if(!e)common.set(id,e={id,naam:a?ps[a]:s.naam,bijdrage:0,paden:[],gv:[],gm:[]});
        e.bijdrage+=c;e.paden.push(("v"+a).toUpperCase()+" x "+("m"+b).toUpperCase());
        if(!e.gv.includes(a.length+1))e.gv.push(a.length+1);if(!e.gm.includes(b.length+1))e.gm.push(b.length+1)}}}
  // volledigheid per generatie van het veulen (generatie 1 = ouders)
  const per=[];for(let g=1;g<=L;g++){const n=Math.pow(2,g);let k=0;if(g===1)k=2;else{const r=g-1;Object.keys(ps).forEach(p=>{if(p.length===r)k++});Object.keys(pm).forEach(p=>{if(p.length===r)k++})}per.push({g,k,n})}
  const known=per.reduce((a,x)=>a+x.k,0),total=per.reduce((a,x)=>a+x.n,0);
  let full=0;for(const x of per){if(x.k<x.n)break;full=x.g}
  const list=[...common.values()].sort((x,y)=>y.bijdrage-x.bijdrage);list.forEach(e=>{e.gv.sort((a,b)=>a-b);e.gm.sort((a,b)=>a-b)});
  return{F,common:list,known,total,gens:L,per,full}}
// Bloedpercentage: aandeel volbloed (xx), Arabisch volbloed (ox) en Anglo-Arabier (AA) in de bekende stamboom.
// Een voorouder met zo'n achtervoegsel telt voor zijn volledige aandeel; daarachter wordt niet verder gezocht.
const BLOOD={xx:/\sxx$/i,ox:/\sox$/i,aa:/\sAA$/};
function bloodType(n){const s=String(n||"").trim();for(const k in BLOOD)if(BLOOD[k].test(s))return k;return""}
function bloodOf(h,L){L=L||COI_GEN;const c=_deepC(h),key="b"+L;if(c[key])return c[key];const ped=deepPed(h,L);const r={xx:0,ox:0,aa:0};
  (function walk(p,w){const n=p?ped[p]:h.naam;if(!n)return;const t=bloodType(n);if(t){r[t]+=w;return}if(p.length>=L)return;walk(p+"v",w/2);walk(p+"m",w/2)})("",1);
  return c[key]=r}
function foalBlood(s,m){const a=bloodOf(s,COI_GEN-1),b=bloodOf(m,COI_GEN-1);return{xx:(a.xx+b.xx)/2,ox:(a.ox+b.ox)/2,aa:(a.aa+b.aa)/2}}
// Populatie voor de verwantschap: paarden in de database uit de laatste 20 jaar met minstens 6 bekende voorouders.
let _pop={src:null,list:null,mean:null};
function population(){if(_pop.src!==state.horses){const y=new Date().getFullYear()-20;
    _pop={src:state.horses,list:state.horses.filter(h=>num(h.geboortejaar)!=null&&num(h.geboortejaar)>=y&&!h.ruin&&ancCount(h)>=6),mean:null,kin:new WeakMap()}}
  return _pop}
// Gemiddelde verwantschapscoëfficiënt van paard h met de populatie (zonder de paarden in skip).
function kinPop(h,skip){const P=population();const ex=new Set([h].concat(skip||[]));let s=0,n=0;
  for(const x of P.list){if(ex.has(x))continue;s+=coi(h,x,KIN_GEN).F;n++}return n?s/n:null}
