const simBlock=()=>Promise.reject(Object.assign(new Error("simulatie: er wordt niets bewaard"),{code:"simulatie"}));
function simDoc(d){return wrapRef(d,{set:simBlock,update:simBlock,delete:simBlock})}
function simColl(c){return wrapRef(c,{doc:(...a)=>simDoc(c.doc(...a)),add:simBlock})}
function simDbOf(r){return{collection:(...a)=>simColl(r.collection(...a)),doc:(...a)=>simDoc(r.doc(...a))}}
function startSim(kind){if(!SIM[kind]||!db)return;if(!state.sim){state.realRole=roleSnapshot();realDb=db;state.realDataRol=document.documentElement.getAttribute("data-rol")}
  if(!realSample&&!realMcp){realSample=sampleNs;realMcp=mcpNs}
  if(sampleNs)sampleNs=simAiStub();if(mcpNs)mcpNs={callTool:()=>Promise.reject(Object.assign(new Error("simulatie: geplande taken worden niet gestart"),{code:"simulatie"}))};
  state.sim=kind;db=simDbOf(realDb);applySimOverlay();document.documentElement.classList.add("fw-sim");renderSimBar();setTab("info");renderAll();window.scrollTo({top:0})}
function stopSim(){if(!state.sim)return;Object.assign(state,state.realRole||{});state.sim=null;if(realDb)db=realDb;
  if(realSample)sampleNs=realSample;if(realMcp)mcpNs=realMcp;realSample=null;realMcp=null;
  if(state.site){if(state.realDataRol)document.documentElement.setAttribute("data-rol",state.realDataRol)}
  document.documentElement.classList.remove("fw-sim");renderSimBar();setTab("admin");renderAll()}
function renderSimBar(){const b=$("simBar");if(!state.sim){b.hidden=true;b.innerHTML="";return}b.hidden=false;
  b.innerHTML=`<span><b>Simulatie</b> · je bekijkt De Fokwijzer als <b>${esc(SIM[state.sim].l)}</b>. Er wordt niets bewaard.</span><span class="row" style="gap:6px"><select id="simSel" aria-label="Andere rol">${Object.entries(SIM).map(([k,v])=>`<option value="${k}" ${k===state.sim?"selected":""}>${esc(v.l)}</option>`).join("")}</select><button class="btn" type="button" id="simStop">Stoppen, terug naar beheerder</button></span>`}
document.addEventListener("click",e=>{const sb=e.target.closest("[data-sim]");if(sb){e.preventDefault();startSim(sb.dataset.sim);return}if(e.target.closest("#simStop")){e.preventDefault();stopSim()}});
document.addEventListener("change",e=>{if(e.target.id==="simSel")startSim(e.target.value)});
// Tijdens de simulatie: accountknoppen (inloggen, partner worden, ...) niet echt uitvoeren.
window.addEventListener("click",e=>{if(!state.sim)return;const ai=e.target.closest(SIM_AI_BTNS);const t=ai||e.target.closest("[data-acct],[data-myp],.fw-hist .btn");if(!t)return;e.preventDefault();e.stopImmediatePropagation();
  const m=document.createElement("div");m.className="sim-toast";m.textContent=ai?"Simulatie: AI en geplande taken worden niet gestart. Voor een echte bezoeker werkt deze knop wel.":"Simulatie: deze knop werkt voor een echte bezoeker, maar nu wordt niets uitgevoerd.";document.body.appendChild(m);setTimeout(()=>m.remove(),3500)},true);
function renderWho(){if(state.site)return;if(state.dbState!=="ready"){$("artWho").innerHTML="";$("adminAcct").innerHTML="";return}const nm=state.meName||(state.isOwner?"Eigenaar":"Jij");const rl=ROL_NAAM[state.rol]||"Lezer";
  const ro=state.dbState==="ready"&&!state.platformWrite;
  const lab=state.sim?`<b>Simulatie</b> - ${esc(SIM[state.sim].l)}`:`<b>${esc(nm)}</b> - ${ro?"Lezer":esc(rl)}${state.isPartner&&!state.isAdmin?" · Partner":""}`;
  $("artWho").innerHTML=`<span class="fw-who">${lab}</span>${state.isAdmin?'<button type="button" class="fw-lnk" id="adminLink">Beheer</button>':""}<button type="button" class="fw-lnk" data-myacct>Mijn account</button><button type="button" class="fw-lnk" data-uitlog>Uitloggen</button>`;
  $("adminAcct").innerHTML=`<span class="muted">Ingelogd als</span><span class="fw-who">${lab}</span><button type="button" class="fw-lnk" data-myacct>Mijn account</button><button type="button" class="fw-lnk" data-uitlog>Uitloggen</button>`}
// "Mijn account": dezelfde mogelijkheden als op de website, met je account als login.
function openMyAccount(){const nm=state.meName||(state.isOwner?"Eigenaar":"Jij");const ro=!state.platformWrite;const rl=ro?"Lezer":(ROL_NAAM[state.rol]||"Gebruiker");
  const d=document.createElement("dialog");d.className="detdlg";
  const rolBtn=!ro&&state.rol==="gebruiker"?'<button class="btn" type="button" data-acct="word-pb">Maak je Fokwijzer-profiel</button>':"";
  const ptBtn=ro?"":(state.isAdmin?"":(state.isPartner?'<button class="btn ghost" type="button" data-myp="uit">Geen partner meer</button>':'<button class="btn" type="button" data-acct="word-partner">Word partner</button>'));
  d.innerHTML=`<div class="dlg-head"><h3 style="margin:0">Mijn account</h3><button type="button" class="btn ghost" data-close>Sluiten</button></div>
   <div class="dlg-body"><dl class="facts" style="margin:0 0 12px"><dt>Naam</dt><dd>${esc(nm)}</dd><dt>Rol</dt><dd><b>${esc(rl)}</b></dd><dt>Partner</dt><dd>${state.isPartner?"ja":"nee"}</dd><dt>Ingelogd via</dt><dd>je account</dd></dl>
   <p class="small muted" style="margin:0 0 12px">${ro?"Je mag deze Fokwijzer alleen bekijken. Vraag de eigenaar om bewerkrechten (Kan bewerken) om bij te dragen.":"Bijdrager: bronnen en opmerkingen aanvullen. Fokwijzer-profiel: eigen paarden toevoegen en gegevens aanpassen. Partner: je bedrijf in de kijker zetten (voorlopig gratis)."}</p>
   <div class="row" style="gap:8px">${rolBtn}${ptBtn}${state.isAdmin?'<button class="btn ghost" type="button" data-goadmin>Naar Beheer</button>':""}</div><div class="status" role="status" id="myStatus"></div>
   <p class="small muted" style="margin:14px 0 0">Wachtwoord en uitloggen regel je bij je account. Op de website van De Fokwijzer log je in met een eigen e-mailadres en wachtwoord.</p></div>`;
  document.body.appendChild(d);d.addEventListener("close",()=>d.remove());d.querySelector("[data-close]").onclick=()=>d.close();
  d.addEventListener("click",async e=>{if(e.target.closest("[data-acct]"))setTimeout(()=>d.close(),400);if(e.target.closest("[data-goadmin]")){d.close();setTab("admin")}
    if(e.target.closest("[data-myp]")){try{await db.collection(LEDEN_COLL).doc(state.meId).update({partner:false});d.close()}catch(err){const st=d.querySelector("#myStatus");st.className="status err";st.textContent="Lukte niet."}}});
  d.showModal()}
function openLogoutInfo(){const d=document.createElement("dialog");d.className="detdlg";
  d.innerHTML=`<div class="dlg-head"><h3 style="margin:0">Uitloggen</h3><button type="button" class="btn ghost" data-close>Sluiten</button></div><div class="dlg-body"><p style="margin:0 0 10px">In deze versie ben je ingelogd met je <b>account</b>. Uitloggen doe je in je account, via je accountmenu. Daarmee meld je je af voor je hele account, niet alleen voor De Fokwijzer.</p><p class="small muted" style="margin:0">Op de website van De Fokwijzer staat hier een gewone knop Uitloggen.</p></div>`;
  document.body.appendChild(d);d.addEventListener("close",()=>d.remove());d.querySelector("[data-close]").onclick=()=>d.close();d.showModal()}
document.addEventListener("click",e=>{if(state.site)return;if(e.target.closest("[data-myacct]")){e.preventDefault();openMyAccount()}else if(e.target.closest("[data-uitlog]")){e.preventDefault();openLogoutInfo()}});
async function renderLeden(){if(state.site||!state.isAdmin)return;const box=$("adminExtra");if(!box)return;
  const L=state.leden||{};const ids=Object.keys(L);let ps={};try{ps=state.userNs&&state.userNs.profiles?await state.userNs.profiles(ids):{}}catch(_){ps={}}
  const rows=ids.sort((a,b)=>String((ps[a]||{}).name||"").localeCompare(String((ps[b]||{}).name||""))).map(id=>{const d=L[id]||{};const nm=(ps[id]&&ps[id].name)||"Onbekende gebruiker";const me=id===state.meId;
    const sel=me&&state.isOwner?'<span class="small">Beheerder (eigenaar)</span>':`<select data-lid="${esc(id)}" aria-label="Rol van ${esc(nm)}">${["gebruiker","paardenbeheerder","beheerder"].map(r=>`<option value="${r}" ${d.rol===r?"selected":""}>${ROL_NAAM[r]}</option>`).join("")}</select>`;
    const n=state.horses.filter(h=>h.eigenaar_id!=null&&String(h.eigenaar_id)===id).length;
    return `<tr><td>${esc(nm)}${me?' <span class="small muted">(jij)</span>':""}</td><td>${sel}</td><td><input type="checkbox" data-lpartner="${esc(id)}" aria-label="${esc(nm)} is partner" ${d.partner?"checked":""}></td><td class="num">${n}</td><td>${esc(d.laatst||"-")}</td></tr>`}).join("");
  box.innerHTML=`<div class="card" style="margin-bottom:12px"><h3 style="margin:0 0 6px">Gebruikers en rollen (${ids.length})</h3><p class="small muted" style="margin:0 0 10px">Iedereen met wie je deze Fokwijzer deelt en die ze opende. Bijdrager: vult bronnen en opmerkingen aan. Fokwijzer-profiel: voegt paarden toe en beheert ze. Beheerder: alles. Wie de pagina alleen mag bekijken, blijft lezer.</p><div class="fw-users-wrap"><table class="fw-users"><tr><th>Naam</th><th>Rol</th><th>Partner</th><th>Eigen paarden</th><th>Laatst gezien</th></tr>${rows||'<tr><td colspan="5" class="small muted">Nog niemand anders opende deze Fokwijzer.</td></tr>'}</table></div><div class="status" role="status" id="ledenStatus"></div></div>`}
// ---------- partners: contact- en betaalgegevens (alleen beheerders) ----------
// Voorlopig zijn alle partners gratis; de betaalgegevens staan klaar voor later.
const PA_ST={gratis:["Gratis","good"],open:["Open","warn"],betaald:["Betaald","good"],achterstallig:["Achterstallig","bad"]};
const PA_PER={maand:"per maand",jaar:"per jaar",eenmalig:"eenmalig"};
const AD_PLEK_KORT={kop:"Kop",hengst:"Hengst",voet:"Voet",veiling:"Veiling",matches:"Matches"};
let paSub=null;
function paColl(){return state.site?"partner_admin":"beheerdata/partners/gegevens"}
function paListen(){if(paSub||!db||!state.isAdmin)return;try{paSub=db.collection(paColl()).onSnapshot(snap=>{state.pAdmin={};snap.docs.forEach(d=>{state.pAdmin[d.id]=d.data()});state.pAdminErr=false;if(state.tab==="admin")renderPartnerOverview()},err=>{state.pAdminErr=true;if(state.tab==="admin")renderPartnerOverview()})}catch(_){state.pAdminErr=true}}
function adZicht(p){const t=new Date().toISOString().slice(0,10);if(p.actief===false)return["Uit","demo"];if(p.van&&p.van>t)return["Vanaf "+p.van,"warn"];if(p.tot&&p.tot<t)return["Verlopen "+p.tot,"bad"];return[p.tot?"Tot "+p.tot:"Actief","good"]}
function paEuro(n){const v=num(n);return v==null?"":"€ "+v.toLocaleString("nl-BE",{minimumFractionDigits:0,maximumFractionDigits:2})}
function renderPartnerOverview(){if(!$("poList"))return;paListen();
  const real=state.partners||[];const L=real.length?real:(state.adDemo===false?[]:AD_DEMO);const A=state.pAdmin||{};const demo=!real.length;
  const nOpen=real.filter(p=>{const a=A[p.id]||{};return a.status==="open"||a.status==="achterstallig"}).length;
  $("poTitle").textContent=`Partners (${real.length})`;
  $("poSum").textContent=demo?"Nog geen echte partners. Hieronder zie je de voorbeeldpartners; zodra je een partner toevoegt, verschijnen hier zijn contact- en betaalgegevens.":(state.pAdminErr?"De betaalgegevens konden niet geladen worden. Alleen wie de Fokwijzer mag bewerken, ziet ze.":(nOpen?`${nOpen} partner${nOpen>1?"s":""} met een openstaande betaling. `:"Voorlopig zijn alle partners gratis. ")+"Alleen beheerders zien deze gegevens.");
  if(!L.length){$("poList").innerHTML='<p class="small muted" style="margin:0">Nog geen partners.</p>';return}
  $("poList").innerHTML=`<table class="fw-users po-table"><tr><th>Partner</th><th>Plek</th><th>Zichtbaar</th><th>Contact</th><th>Tarief</th><th>Betaling</th><th></th></tr>${L.map(p=>{const a=A[p.id]||{};const z=adZicht(p);const st=PA_ST[a.status||"gratis"];
    return `<tr><td><span class="po-name">${adLogo(p,26,26)}<span><b>${esc(p.naam)}</b>${p.titel?`<span class="small muted">${esc(p.titel)}</span>`:""}</span></span></td><td>${esc(AD_PLEK_KORT[p.type]||p.type||"")}</td><td><span class="chip ${z[1]}">${esc(z[0])}</span></td><td class="small">${a.contact?esc(a.contact):""}${a.email?`<br><a href="mailto:${esc(a.email)}">${esc(a.email)}</a>`:""}${!a.contact&&!a.email?'<span class="muted">-</span>':""}</td><td class="small">${a.tarief?esc(paEuro(a.tarief))+" "+esc(PA_PER[a.periode]||""):'<span class="muted">gratis</span>'}</td><td>${demo?'<span class="chip demo">voorbeeld</span>':st?`<span class="chip ${st[1]}">${st[0]}</span>${a.betaald_tot?`<div class="small muted">tot ${esc(a.betaald_tot)}</div>`:""}`:'<span class="muted small">niet ingevuld</span>'}</td><td>${demo?"":`<button class="btn ghost" type="button" data-pa="${esc(p.id)}">Gegevens</button>`}</td></tr>`}).join("")}</table>`}
function openPartnerAdmin(id){const p=(state.partners||[]).find(x=>x.id===id);if(!p)return;const a=(state.pAdmin||{})[id]||{};
  const f=(k,l,type,ph)=>`<div class="field"><label class="label" for="pa-${k}">${l}</label><input id="pa-${k}" type="${type||"text"}" value="${esc(a[k]||"")}" ${ph?`placeholder="${esc(ph)}"`:""}></div>`;
  const d=document.createElement("dialog");d.className="detdlg padlg";
  d.innerHTML=`<div class="dlg-head"><h3 style="margin:0;display:flex;gap:10px;align-items:center">${adLogo(p,28,28)} ${esc(p.naam)}</h3><button type="button" class="btn ghost" data-close>Sluiten</button></div>
  <form class="dlg-body" novalidate>
   <div class="label" style="margin-bottom:6px">Contact</div>
   <div class="grid3">${f("contact","Contactpersoon")}${f("email","E-mail","email","naam@bedrijf.be")}${f("telefoon","Telefoon","tel")}</div>
   <div class="label" style="margin:12px 0 6px">Facturatie</div>
   <div class="grid3">${f("bedrijf","Bedrijfsnaam")}${f("btw","BTW-nummer","text","BE0123.456.789")}${f("adres","Facturatieadres")}</div>
   <div class="label" style="margin:12px 0 6px">Betaling <span class="muted" style="text-transform:none;letter-spacing:0">(voorlopig is alles gratis; vul dit in zodra partners betalen)</span></div>
   <div class="grid3">${f("tarief","Tarief (€)","number")}<div class="field"><label class="label" for="pa-periode">Periode</label><select id="pa-periode">${Object.entries(PA_PER).map(([k,v])=>`<option value="${k}" ${a.periode===k?"selected":""}>${v}</option>`).join("")}</select></div><div class="field"><label class="label" for="pa-status">Betaalstatus</label><select id="pa-status">${Object.entries(PA_ST).map(([k,v])=>`<option value="${k}" ${(a.status||"gratis")===k?"selected":""}>${v[0]}</option>`).join("")}</select></div>
   ${f("factuur","Laatste factuurnummer")}${f("betaald_op","Laatst betaald op","date")}${f("betaald_tot","Betaald tot","date")}</div>
   <div class="field" style="margin-top:10px"><label class="label" for="pa-notities">Notities</label><textarea id="pa-notities" rows="3" maxlength="2000">${esc(a.notities||"")}</textarea></div>
   <div class="row" style="margin-top:12px;gap:8px"><button class="btn" type="submit">Gegevens bewaren</button><button class="btn ghost" type="button" data-edit-ad>Advertentie bewerken</button>${p.url?`<a class="btn ghost" href="${esc(p.url)}" target="_blank" rel="noopener">Website partner</a>`:""}</div>
   <div class="status" role="status"></div></form>`;
  document.body.appendChild(d);d.addEventListener("close",()=>d.remove());d.querySelector("[data-close]").onclick=()=>d.close();
  d.querySelector("[data-edit-ad]").onclick=()=>{d.close();adFill(p);setTab("partners");$("adNaam").focus()};
  d.querySelector("form").addEventListener("submit",async e=>{e.preventDefault();const st=d.querySelector(".status");const out={};["contact","email","telefoon","bedrijf","btw","adres","tarief","factuur","betaald_op","betaald_tot","notities"].forEach(k=>{const v=d.querySelector("#pa-"+k).value.trim();if(v)out[k]=k==="tarief"?num(v):v});
    out.periode=d.querySelector("#pa-periode").value;const sv=d.querySelector("#pa-status").value;if(sv)out.status=sv;out.bijgewerkt=new Date().toISOString().slice(0,10);
    if(out.email&&!/^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(out.email)){st.className="status err";st.textContent="Dit e-mailadres klopt niet.";return}
    try{await db.collection(paColl()).doc(id).set(out);st.className="status ok";st.textContent="Bewaard."}catch(err){st.className="status err";st.textContent="Bewaren lukte niet: "+(err&&err.message||"onbekende fout")}});
  d.showModal()}
// Partners-pagina: zonder beheerdersrechten een duidelijke melding in plaats van het formulier.
function renderPartnersNote(){const ready=state.dbState==="ready";const adm=!!state.isAdmin&&ready;const pt=!!state.isPartner&&ready;let n="";
  const uitleg='Als <b>partner</b> zet je je bedrijf of dienst in de kijker: je logo rechtsboven in de kop, als sponsor bij je hengsten, onderaan elke pagina of bij Beste matches. Je kunt tegelijk bijdrager zijn of een Fokwijzer-profiel hebben. Voorlopig is partner zijn <b>gratis</b>.';
  if(!ready)n='<p class="small muted">Rechten worden gecontroleerd...</p>';
  else if(adm)n="";
  else if(pt)n='<p class="small muted" style="margin:0 0 10px">Je bent partner. Hier beheer je je eigen partnerplekken; een beheerder van De Fokwijzer kan ze ook aanpassen.</p>';
  else if(state.site&&(state.rol||"anoniem")==="anoniem")n=`<div class="card pb-cta"><h3 style="margin:0">Partner worden</h3><p style="margin:6px 0 12px">${uitleg} Maak een account en vink <b>Ik wil ook partner worden</b> aan, of log in.</p><div class="row"><button class="btn" type="button" data-acct="registreren-partner">Account maken als partner</button><button class="btn ghost" type="button" data-acct="inloggen">Ik heb al een account: inloggen</button></div></div>`;
  else if(!state.site&&!state.platformWrite)n='<div class="banner"><strong>Alleen lezen.</strong> Je mag deze Fokwijzer bekijken maar niet bewerken. Vraag de eigenaar om bewerkrechten als je partner wilt worden.</div>';
  else n=`<div class="card pb-cta"><h3 style="margin:0">Word partner</h3><p style="margin:6px 0 12px">${uitleg} Je account blijft verder hetzelfde.</p><div class="row"><button class="btn" type="button" data-acct="word-partner">Word partner</button></div><div class="status" role="status" id="ptStatus"></div></div>`;
  $("partnersNote").innerHTML=n;$("adCard").style.display=adm||pt?"":"none"}
function renderAdmin(){renderLeden();renderPartnerOverview();renderSa();const al=$("adminLink");if(al)al.setAttribute("aria-current",state.tab==="admin"?"page":"false")}
function renderAll(){const adm=state.site?state.isAdmin:(state.dbState==="ready"?!!state.isAdmin:true);document.documentElement.classList.toggle("fw-ro",!adm);if(!adm&&state.tab==="admin")state.tab="info";renderWho();renderBanner();fillSelects();renderTab();renderAds()}
const P_COLL="partners";
// Tijdelijk logo voor de voorbeeldpartner; vervang door het echte logo van DeDilieHoeve.
const FW_DDH="data:image/svg+xml;base64,";
const AD_DEMO=[
 {id:"vb-kop",type:"kop",naam:"DeDilieHoeve",tekst:"Dekseizoen 2027 open",logo:FW_DDH,url:""},
 {id:"vb-hengst",type:"hengst",naam:"DeDilieHoeve",logo:FW_DDH,hengst_naam:"Darry Lou Z",dekinfo:"dekgeld en beschikbaarheid",url:""},
 {id:"vb-v1",type:"voet",naam:"DeDilieHoeve",titel:"Voeders",logo:FW_DDH},{id:"vb-v2",type:"voet",naam:"DeDilieHoeve",titel:"Transport",logo:FW_DDH},{id:"vb-v3",type:"voet",naam:"DeDilieHoeve",titel:"Verzekering",logo:FW_DDH},{id:"vb-v4",type:"voet",naam:"DeDilieHoeve",titel:"Hoefsmid",logo:FW_DDH},
 {id:"vb-veil",type:"veiling",naam:"DeDilieHoeve",logo:FW_DDH,titel:"DeDilieHoeve veiling, online 14 tot 21 november",tekst:"32 veulens en 6 springpaarden · collectie nu online",knop:"Bekijk collectie",url:""},
 {id:"vb-match",type:"matches",naam:"DeDilieHoeve",titel:"Fokkerijkliniek DeDilieHoeve",logo:FW_DDH,tekst:"Inseminatie, embryotransfer en drachtigheidscontrole voor jouw gekozen combinatie",knop:"Afspraak maken",url:""}
].map(x=>Object.assign(x,{voorbeeld:true}));
function adActive(p){const t=new Date().toISOString().slice(0,10);return p.actief!==false&&(!p.van||p.van<=t)&&(!p.tot||p.tot>=t)}
function adsAll(){const real=(state.partners||[]);if(real.length)return real.filter(adActive);return state.adDemo===false?[]:AD_DEMO}
function adsOf(t){return adsAll().filter(p=>p.type===t)}
function adInit(n){const w=String(n||"?").replace(/\b(voorbeeld|bv|bvba|nv)\b/ig,"").trim().split(/\s+/).filter(Boolean);return ((w[0]||"?")[0]+(w[1]?w[1][0]:"")).toUpperCase()}
function adLogo(p,w,h){return `<span class="ad-logo" style="width:${w}px;height:${h}px">${p.logo&&/^data:image\//.test(p.logo)?`<img src="${esc(p.logo)}" alt="">`:esc(adInit(p.naam))}</span>`}
function adWrap(p,inner,cls){const u=p.url&&/^https?:\/\//.test(p.url)?p.url:"";return u?`<a class="ad ${cls||""}" href="${esc(u)}" target="_blank" rel="sponsored noopener" title="${esc(p.naam)}">${inner}</a>`:`<div class="ad ${cls||""}" title="${esc(p.naam)}">${inner}</div>`}
function sponsorOf(h){if(!h||h.geslacht!=="hengst")return null;const ks=hKeys(h);return adsOf("hengst").find(p=>(p.hengst_id&&p.hengst_id===h.id)||(p.hengst_naam&&ks.has(keyL(p.hengst_naam))))||null}
function adKopHtml(k){return adWrap(k,`<span class="ad-tag">Partner</span>${adLogo(k,32,32)}<span class="ad-txt"><b>${esc(k.naam)}</b>${k.tekst?`<span>${esc(k.tekst)}</span>`:""}</span>`,"ad-kop")}
function adVoetHtml(v){return `<div class="ad-strip"><div class="ad-strip-head"><span class="ad-tag">Partners</span><span class="ad-strip-note">Zij maken De Fokwijzer gratis mogelijk${v.some(p=>p.voorbeeld)?" · voorbeeld":""}</span></div><div class="ad-voet-row">${v.slice(0,6).map(p=>adWrap(p,`${adLogo(p,34,34)}<span class="ad-vt"><b>${esc(p.titel||p.naam)}</b>${p.titel?`<span>${esc(p.naam)}</span>`:""}</span>`,"ad-voet")).join("")}</div></div>`}
function adVeilHtml(vb){return adWrap(vb,`${adLogo(vb,96,48)}<div class="ad-body"><div><span class="ad-tag">Partner</span> <b style="font-size:1.02rem">${esc(vb.titel||vb.naam)}</b></div>${vb.tekst?`<div class="ad-sub">${esc(vb.tekst)}</div>`:""}</div>${vb.knop?`<span class="btn">${esc(vb.knop)}</span>`:""}`,"ad-banner")}
function adMatchHtml(mc){return adWrap(mc,`<span class="ad-tag">Partner</span>${adLogo(mc,40,40)}<div class="ad-body"><b>${esc(mc.titel||mc.naam)}</b>${mc.tekst?`<div class="ad-sub">${esc(mc.tekst)}</div>`:""}</div>${mc.knop?`<span class="btn ghost">${esc(mc.knop)}</span>`:""}`,"ad-card")}
function adDekHtml(sp){return adWrap(sp,`<span class="ad-tag">Partner</span><span class="ad-msg">Dekt bij <b>${esc(sp.naam)}</b> · ${esc(sp.dekinfo)}</span>${sp.url?'<span class="ad-cta">Bekijk</span>':""}`,"ad-dek")}
function renderAds(){
  const k=adsOf("kop")[0];$("adKop").innerHTML=k?adKopHtml(k):"";
  const v=adsOf("voet");$("adVoet").innerHTML=v.length?adVoetHtml(v):"";
  const vb=adsOf("veiling")[0];$("adVeil").innerHTML=vb?adVeilHtml(vb):"";
  const mc=adsOf("matches")[0];$("adMatch").innerHTML=mc?adMatchHtml(mc):"";
  if(state.tab==="partners")renderAdAdmin();if(state.tab==="admin")renderPartnerOverview()}


function renderBanner(){const n=state.horses.length;const h=state.horses.filter(x=>x.geslacht==="hengst").length;
  if(!state.loaded&&state.dbState!=="none"){$("count").innerHTML="";$("banner").innerHTML="";return}$("count").innerHTML=`<span class="num">${n}</span> paarden &middot; <span class="num">${h}</span> hengsten &middot; <span class="num">${n-h}</span> merries`;
  let msg="";
  if(state.demo){msg=`<div class="banner"><strong>Voorbeeldmodus.</strong> Je ziet fictieve paarden (gemarkeerd met "demo") zodat je kunt uittesten hoe zoeken, het virtuele veulen en matchen werken. Zodra je zelf een paard toevoegt of importeert, verdwijnen de voorbeelden.${state.dbState==="none"?" De gedeelde opslag is in deze weergave niet beschikbaar, dus toevoegen kan hier niet.":""}</div>`}
  $("banner").innerHTML=msg}

function stamboeken(){return[...new Set(state.horses.map(h=>h.stamboek).filter(Boolean))].sort()}
function fillSelects(){const fs=$("fStb"),cur=fs.value;fs.innerHTML='<option value="">Alle</option>'+stamboeken().map(s=>`<option ${s===cur?"selected":""}>${esc(s)}</option>`).join("");
  const sorted=[...state.horses].sort((a,b)=>String(a.naam).localeCompare(String(b.naam)));
  const opt=(arr,cur,ph)=>`<option value="">${ph}</option>`+arr.map(h=>`<option value="${esc(h.id)}" ${h.id===cur?"selected":""}>${esc(h.naam)}${h.geboortejaar?" ("+esc(h.geboortejaar)+")":""}</option>`).join("");
  const cs=$("cS").value,cm=$("cM").value,mf=$("mFor").value;
  $("cS").innerHTML=opt(sorted.filter(h=>h.geslacht==="hengst"&&!h.ruin),cs,"Kies een hengst");
  $("cM").innerHTML=opt(sorted.filter(h=>h.geslacht==="merrie"),cm,"Kies een merrie");
  {const st=sorted.filter(h=>h.geslacht==="hengst"&&!h.ruin),hv=[0,1,2,3].map(i=>$("hc"+i).value),hm=$("hcM").value;
   [0,1,2,3].forEach(i=>{$("hc"+i).innerHTML=opt(st,hv[i],i<2?"Kies een hengst":"Kies een hengst (optioneel)")});
   $("hcM").innerHTML=opt(sorted.filter(h=>h.geslacht==="merrie"),hm,"Geen merrie")}
  $("mFor").innerHTML=opt(sorted,mf,"Kies een hengst of merrie");
  if(state.demo){if(!$("cS").value&&byId("demo-astor"))$("cS").value="demo-astor";if(!$("cM").value&&byId("demo-aria"))$("cM").value="demo-aria";if(!$("mFor").value&&byId("demo-aria"))$("mFor").value="demo-aria"}}

function renderSearch(){const q=norm($("q").value),sx=$("fSex").value,sb=$("fStb").value,so=$("fSort").value;
  let list=state.horses.filter(h=>{if(sx&&h.geslacht!==sx)return false;if(sb&&h.stamboek!==sb)return false;if(!q)return true;
    const hay=[h.naam,h.ueln,h.fei_id,h.stamboom&&h.stamboom.v,h.stamboom&&h.stamboom.m,h.stamboom&&h.stamboom.mv].map(norm).join("|");return hay.includes(q)});
  const key={naam:(h)=>String(h.naam).toLowerCase(),niveau:(h)=>-(num(h.hoogste_niveau_cm)||0),fok:(h)=>-(zOf(h)==null?-99:zOf(h)),jaar:(h)=>-(num(h.geboortejaar)||0)}[so];
  let fuzzy=false;
  if(!list.length&&q){list=closeMatches($("q").value,state.horses.filter(h=>(!sx||h.geslacht===sx)&&(!sb||h.stamboek===sb)));fuzzy=list.length>0}
  if(!fuzzy)list.sort((a,b)=>{const x=key(a),y=key(b);return x<y?-1:x>y?1:0});
  if(!list.length&&!state.loaded&&state.dbState!=="none"){$("results").innerHTML='<div class="empty">Paarden worden geladen...</div>';$("detail").innerHTML="";return}if(!list.length){$("results").innerHTML=`<div class="empty">Geen paarden gevonden. Pas je zoekterm of filters aan${state.demo?"":", of voeg een paard toe via Paarden beheren"}.</div>`}
  else $("results").innerHTML=(fuzzy?`<div class="small muted" style="padding:8px 14px;border-bottom:1px solid var(--line)">Geen exacte treffer. Deze namen lijken erop:</div>`:"")+list.map(h=>{const z=zOf(h);const tc=h.record_status==="te_controleren";return `<button class="item ritem${tc?" flag":""}" data-id="${esc(h.id)}" aria-current="${h.id===state.sel}">${sexChip(h)}
    <span style="min-width:0"><span class="nl"><span class="name">${esc(h.naam)}</span>${num(h.hoogste_niveau_cm)!=null?`<span class="lvl" title="Hoogste niveau">${fmtH(h.hoogste_niveau_cm)}</span>`:""}${z!=null?`<span class="lvl sd ${z>=.5?"good":""}" title="Fokwaarde t.o.v. gemiddelde">${fz(z)} SD</span>`:""}${(()=>{const sp=sponsorOf(h);return sp?`<span class="ad-badge" title="Gesponsord door ${esc(sp.naam)}">${adLogo(sp,16,16)}<span class="ad-tag" style="padding:2px 4px">Gesponsord</span></span>`:""})()}</span><span class="small muted sub">${esc(h.stamboom&&h.stamboom.v||"?")} x ${esc(h.stamboom&&h.stamboom.mv||"?")} &middot; ${esc(h.stamboek||"stamboek onbekend")}${h.geboortejaar?" &middot; "+esc(h.geboortejaar):""}</span></span>${tc?'<span class="rflag" title="De gegevens van dit paard moeten nog gecontroleerd worden">Te controleren</span>':""}</button>`}).join("");
  if(!state.sel||!list.some(h=>h.id===state.sel))state.sel=list[0]?list[0].id:null;
  renderDetail()}

function pedHtml(h){const s=pedOf(h);const cell=(k,cls,col,row)=>{const v=s[k];return `<div class="${cls} ${v?"":"unk"}" style="grid-column:${col};grid-row:${row}"><b>${(PED_LABEL[k]||k.toUpperCase())}</b>${v?esc(v):"onbekend"}</div>`};
  let out='<div class="ped">'+cell("v","g1",1,"1 / span 4")+cell("m","g1",1,"5 / span 4");
  ["vv","vm","mv","mm"].forEach((k,i)=>out+=cell(k,"g2",2,(1+i*2)+" / span 2"));
  ["vvv","vvm","vmv","vmm","mvv","mvm","mmv","mmm"].forEach((k,i)=>out+=cell(k,"g3",3,String(i+1)));
  return out+"</div>"}

function pedMini(h){const s=pedOf(h);const c=(k,cls,col,row)=>{const v=s[k];return `<div class="${cls}${v?"":" unk"}" style="grid-column:${col};grid-row:${row}" title="${esc((PED_LABEL[k]||k.toUpperCase())+": "+(v||"onbekend"))}"><span>${v?esc(v):"?"}</span></div>`};
  let o='<div class="ped mini">'+c("v","g1",1,"1 / span 2")+c("m","g1",1,"3 / span 2");
  ["vv","vm","mv","mm"].forEach((k,i)=>o+=c(k,"g2",2,String(i+1)));
  ["vvv","vvm","vmv","vmm","mvv","mvm","mmv","mmm"].forEach((k,i)=>o+=c(k,"g3",3+(i%2),String(1+(i>>1))));
  return o+"</div>"}
// ---------- Stamboom in Fokwijzer-stijl (wikigids-klassiek) ----------
const PC_G2=["vv","vm","mv","mm"],PC_G3=["vvv","vvm","vmv","vmm","mvv","mvm","mmv","mmm"];
