  let fsz=Math.max(opt.minPx?12:0,15*tf);c.font=`400 ${fsz}px ${BODY}`;while(c.measureText(facts).width>tMax&&fsz>(opt.minPx?12:9)){fsz-=.5;c.font=`400 ${fsz}px ${BODY}`}
  const gapK=Math.max(7,kSz*.85),gapT=Math.max(6,tsz*.3);
