  const fY=cmp?H-Math.max(12,ffs*.6):H-Math.max(14,sp(22)),lY=cmp?(two?fY-ascF-Math.max(14,lf*.6)-lf*.3:fY):Math.min(H-Math.max(16,sp(48)),fY-ascF-Math.max(14,lf*.6)-lf*.3),gridEnd=lY-Math.max(ascL,cmp&&!two?ascF:0)-16;
