// ---------- praktische hengstinfo (dekinfo) ----------
// Bij een hengst: h.dek = {dekgeld, sperma:[vers|diepvries|natuurlijk], beschikbaar:beschikbaar|beperkt|niet, seizoen, toelichting, station, url, bijgewerkt}
const SPERMA=[["vers","Vers sperma"],["diepvries","Diepvriessperma"],["natuurlijk","Natuurlijke dekking"]];
const BESCHIK={beschikbaar:["Beschikbaar","good"],beperkt:["Beperkt beschikbaar","warn"],niet:["Niet beschikbaar","bad"]};
const okUrl=(u)=>typeof u==="string"&&/^https?:\/\/[^\s/]+\.[^\s]+$/i.test(u.trim());
function dekOf(h){const d=h&&h.geslacht==="hengst"&&h.dek;return d&&typeof d==="object"?d:null}
function dekLeeg(d){return !d||!(d.dekgeld||(d.sperma||[]).length||d.beschikbaar||d.seizoen||d.toelichting||d.station||d.url)}
const spermaTxt=(d)=>(d&&d.sperma||[]).map(k=>(SPERMA.find(x=>x[0]===k)||[k,k])[1]);
const beschikTxt=(d)=>d&&BESCHIK[d.beschikbaar]?BESCHIK[d.beschikbaar][0]:"";
const dagTxt=(iso)=>{try{const d=new Date(iso);return isNaN(d)?String(iso):d.toLocaleDateString("nl-BE",{day:"numeric",month:"long",year:"numeric"})}catch(_){return String(iso)}};
function stationHtml(d){return `${d.station?esc(d.station):""}${okUrl(d.url)?`${d.station?"<br>":""}<a href="${esc(d.url.trim())}" target="_blank" rel="noopener">Website van het station</a>`:""}`||'<span class="muted">onbekend</span>'}
function dekHtml(h,compact){const d=dekOf(h)||{};const unk='<span class="muted">onbekend</span>';
  if(dekLeeg(d))return '<p class="small muted" style="margin:0">Nog geen dekinfo bekend voor deze hengst.</p>';
  const b=BESCHIK[d.beschikbaar];
  return `<dl class="facts two">
   <dt>Dekgeld</dt><dd class="wide">${d.dekgeld?esc(d.dekgeld):unk}</dd>
   <dt>Sperma</dt><dd class="wide">${(d.sperma||[]).length?`<span class="chips">${spermaTxt(d).map(x=>`<span class="chip">${esc(x)}</span>`).join("")}</span>`:unk}</dd>
   <dt>Beschikbaarheid</dt><dd class="wide">${b?`<span class="chip ${b[1]}">${b[0]}</span>`:unk}${d.seizoen?` <span class="small muted">dekseizoen ${esc(d.seizoen)}</span>`:""}${d.toelichting?`<div class="small" style="margin-top:4px">${esc(d.toelichting)}</div>`:""}</dd>
   <dt>Station</dt><dd class="wide">${stationHtml(d)}</dd>
  </dl>${compact?"":`<p class="small muted" style="margin:10px 0 0">${d.herkomst==="automatisch"?`<span>Automatisch opgezocht</span>${d.bron&&okUrl(d.bron.url)?` <span>(bron:</span> <a href="${esc(d.bron.url)}" target="_blank" rel="noopener">${esc(d.bron.naam||"bron")}</a>)`:""}. `:""}${d.bijgewerkt?`<span>Laatst bijgewerkt:</span> <span>${esc(dagTxt(d.bijgewerkt))}</span>. `:""}Controleer dekgeld en beschikbaarheid altijd bij het station.</p>`}`}
// Invulvelden voor de dekinfo (formulier Paarden beheren en snel aanpassen bij de hengst). p = voorvoegsel van de id's.
function dekFormHtml(p){return `<div class="grid3">
   <div class="field"><label class="label" for="${p}-dekgeld">Dekgeld</label><input id="${p}-dekgeld" maxlength="160" placeholder="bv. € 1.500 + € 500 bij dracht"></div>
   <div class="field"><label class="label" for="${p}-beschik">Beschikbaarheid</label><select id="${p}-beschik"><option value="">Onbekend</option><option value="beschikbaar">Beschikbaar</option><option value="beperkt">Beperkt beschikbaar</option><option value="niet">Niet beschikbaar</option></select></div>
   <div class="field"><label class="label" for="${p}-seizoen">Dekseizoen</label><input id="${p}-seizoen" maxlength="20" placeholder="bv. 2027"></div>
   <div class="field"><label class="label" for="${p}-station">Station</label><input id="${p}-station" maxlength="120" placeholder="Naam van het hengstenstation"></div>
   <div class="field"><label class="label" for="${p}-stationurl">Link naar het station</label><input id="${p}-stationurl" inputmode="url" autocomplete="url" spellcheck="false" maxlength="500" placeholder="https://..."></div>
   <div class="field"><label class="label" for="${p}-dektoel">Toelichting</label><input id="${p}-dektoel" maxlength="300" placeholder="bv. diepvries ook in het buitenland"></div>
  </div>
  <fieldset class="dek-sp"><legend class="label">Sperma</legend>${SPERMA.map(([k,l])=>`<label><input type="checkbox" id="${p}-sp-${k}"> ${l}</label>`).join("")}</fieldset>`}
function setDekForm(p,d){d=d||{};const s=(k,v)=>{const e=$(p+"-"+k);if(e)e.value=v==null?"":v};s("dekgeld",d.dekgeld);s("beschik",d.beschikbaar||"");s("seizoen",d.seizoen);s("station",d.station);s("stationurl",d.url);s("dektoel",d.toelichting);
  SPERMA.forEach(([k])=>{const e=$(p+"-sp-"+k);if(e)e.checked=(d.sperma||[]).includes(k)})}
function readDekForm(p){const g=(k)=>{const e=$(p+"-"+k);return e?e.value.trim():""};const d={};
  [["dekgeld","dekgeld"],["beschikbaar","beschik"],["seizoen","seizoen"],["station","station"],["url","stationurl"],["toelichting","dektoel"]].forEach(([k,id])=>{const v=g(id);if(v)d[k]=v});
  if(d.url&&!/^https?:\/\//i.test(d.url))d.url="https://"+d.url;
  const sp=SPERMA.map(x=>x[0]).filter(k=>{const e=$(p+"-sp-"+k);return e&&e.checked});if(sp.length)d.sperma=sp;return d}
function dekGelijk(a,b){const k=(d)=>JSON.stringify(["dekgeld","beschikbaar","seizoen","toelichting","station","url"].map(x=>(d&&d[x])||"").concat([(d&&d.sperma||[]).join(",")]));return k(a)===k(b)}
function dekFsShow(){const f=$("dekFs");if(f)f.hidden=$("h-geslacht").value!=="hengst"}
function compHtml(r){const lab={gen:"Genetische indexen",perf:"Prestaties en nakomelingen",coi:"Inteelt",health:"Gezondheid",data:"Datavolledigheid"};
  return '<div class="bars">'+Object.keys(lab).map(k=>{const v=r.comps[k];return `<div class="bar"><span>${lab[k]} <span class="muted small">(${state.w[k]})</span></span><div class="track"><div class="fill" style="width:${v==null?0:v}%"></div></div><span class="num" style="text-align:right">${v==null?"geen":Math.round(v)}</span></div>`}).join("")+"</div>"}
function warnHtml(r){return r.warnings.length?'<div class="chips" style="margin-top:10px">'+r.warnings.map(w=>`<span class="chip ${w.lvl}">${esc(w.t)}</span>`).join("")+"</div>":""}

// ---------- virtueel veulen: inteelt, bloedpercentage, verwantschap en lijnen ----------
const p1=(f)=>(f*100).toLocaleString("nl-BE",{maximumFractionDigits:1})+"%";
function bloodHtml(b){const parts=[["xx","volbloed (xx)"],["ox","Arabisch volbloed (ox)"],["aa","Anglo-Arabier (AA)"]].filter(([k])=>b[k]>=.0005);
  return parts.length?parts.map(([k,l])=>`<span><span class="num" style="font-weight:600">${p1(b[k])}</span> ${l}</span>`).join('<span class="muted" aria-hidden="true"> · </span>'):'<span class="muted">geen volbloed in de bekende stamboom</span>'}
function coiHtml(c,titel){const Fp=c.F*100,lvl=Fp>=state.t.max?"bad":Fp>=KWPN_COI?"warn":"good";
  const row=(e)=>`<tr><th scope="row">${esc(e.naam)}</th><td class="num">${e.gv.join(", ")} x ${e.gm.join(", ")}</td><td class="num">${e.paden.length}</td><td class="num">${e.bijdrage<.00005?"&lt;0,01%":pct(e.bijdrage)}</td></tr>`;
  const head='<thead><tr><th>Voorouder</th><th>Generatie (vader x moeder)</th><th>Paden</th><th>Bijdrage</th></tr></thead>';
  const top=c.common.slice(0,12),rest=c.common.slice(12);
  return `<h3 style="margin-top:16px">${titel||"Inteelt van het veulen"}</h3>
    <p style="margin:4px 0"><span class="num" style="font-weight:600;font-size:1.3em">${pct(c.F)}</span> <span class="chip ${lvl}">${Fp>=KWPN_COI?"boven":"onder"} het KWPN-advies van ${fn(KWPN_COI)}%</span></p>
    <p class="small muted" style="margin:2px 0 8px">(Wright, ${c.gens} generaties, ${c.known} van ${c.total} voorouders bekend)</p>
    ${c.full<c.gens?`<p class="small muted" style="margin:0 0 8px">Volledig bekend tot generatie ${c.full}. Voorouders die ontbreken kunnen inteelt verbergen, dus het echte percentage kan hoger liggen.</p>`:""}
    ${top.length?`<div class="label" style="margin:8px 0 4px">Voorouders die langs vaders- en moederskant voorkomen</div><div class="tablewrap"><table class="coi-tab">${head}<tbody>${top.map(row).join("")}</tbody></table></div>
      ${rest.length?`<details style="margin-top:6px"><summary class="small">Nog ${rest.length} voorouders met een kleinere bijdrage</summary><div class="tablewrap" style="margin-top:6px"><table class="coi-tab">${head}<tbody>${rest.map(row).join("")}</tbody></table></div></details>`:""}
      <p class="small muted" style="margin:6px 0 0">Generatie 1 zijn de ouders, 2 de grootouders, enzovoort. "4 x 5" betekent dat de voorouder in de 4de generatie langs vaderskant en in de 5de langs moederskant staat.</p>`
     :'<p class="small muted" style="margin:0">Geen gemeenschappelijke voorouders gevonden in de bekende stamboom.</p>'}`}
function foalFactsHtml(s,m,kinId,stamId){kinId=kinId||"fkKin";if(stamId===undefined)stamId=m.id;const vl=[s.naam].concat(lineOf(s,"v")),ml=[m.naam].concat(lineOf(m,"m"));
  const rh=byName(ml[ml.length-1]),st=rh?stamOf(rh):"";const chain=(a)=>a.map(esc).join(' <span class="muted" aria-hidden="true">›</span> ');
  return `<div class="foal-facts">
    <div><div class="label">Bloedpercentage</div><div>${bloodHtml(foalBlood(s,m))}</div><div class="small muted">Aandeel volbloed in de bekende stamboom, tot ${COI_GEN} generaties.</div></div>
    <div><div class="label">Verwantschap met de populatie</div><div id="${esc(kinId)}"><span class="small muted">Wordt berekend...</span></div></div>
    <div><div class="label">Vaderlijn</div><div class="small">${chain(vl)}</div></div>
    <div><div class="label">Moederlijn</div><div class="small">${chain(ml)}${st?` <span class="chip">stam ${esc(st)}</span>`:""}</div>${FW_EXTRA.stamlijnen&&stamId?`<button type="button" class="btn ghost" data-stamvan="${esc(stamId)}" style="margin-top:6px;padding:4px 10px;font-size:13px">Bekijk de stamlijn</button>`:""}</div>
  </div>`}
// De verwantschap vraagt honderden berekeningen: na het tonen van de pagina, en bewaard per combinatie.
// Toont de verwantschap in vak elId; geldig() zegt of het vak nog bij dezelfde ouders hoort.
function kinVak(elId,s,m,key,geldig){const P=population();P.foal=P.foal||new Map();
  const show=(r)=>{const e=$(elId);if(!e||!geldig())return;
    if(!r){e.innerHTML='<span class="small muted">Te weinig paarden met een bekende stamboom om dit te berekenen.</span>';return}
    const rel=r.mean?r.kin/r.mean:null,lab=rel==null?null:rel<.85?["unieker dan gemiddeld","good"]:rel>1.15?["meer verwant dan gemiddeld","warn"]:["ongeveer gemiddeld",""];
    e.innerHTML=`<span class="num" style="font-weight:600">${pct(r.kin)}</span> ${lab?`<span class="chip ${lab[1]}">${lab[0]}</span>`:""}
      <div class="small muted">Gemiddelde verwantschap met ${r.n} paarden uit de database, geboren in de laatste 20 jaar${r.mean!=null?` (onderling gemiddeld ${pct(r.mean)})`:""}. Zoveel inteelt krijgt een veulen gemiddeld als je dit paard later met een van hen kruist: lager is unieker. Berekend over ${KIN_GEN} generaties.</div>`};
  if(P.foal.has(key)){show(P.foal.get(key));return}
  setTimeout(()=>{if(!geldig())return;const r=foalKin(s,m);P.foal.set(key,r);show(r)},30)}
function fillFoalKin(s,m){kinVak("fkKin",s,m,s.id+"|"+m.id,()=>$("cS").value===s.id&&$("cM").value===m.id)}

function renderCompare(){const s=byId($("cS").value),m=byId($("cM").value);
  if(!s||!m){$("cmpOut").innerHTML='<div class="card empty">Kies een hengst en een merrie om ze naast elkaar te zetten.</div>';renderCouncil(null,null);return}
  const r=match(s,m);const row=(l,a,b)=>`<tr><th scope="row">${l}</th><td>${a}</td><td>${b}</td></tr>`;const o=(h)=>h.nakomelingen||{};
  const nk=(h)=>num(o(h).sport)!=null?`<span class="num">${esc(o(h).sport)}</span> / <span class="num">${esc(o(h).m140||0)}</span> / <span class="num">${esc(o(h).m150||0)}</span>`:"onbekend";
  const zz=(h)=>{const z=zOf(h);return z==null?"onbekend":`<span class="num">${fz(z,2)}</span> SD`};
  $("cmpOut").innerHTML=`<div class="split" style="margin-top:0">
   <div class="tablewrap"><table><thead><tr><th></th><th>${esc(s.naam)}</th><th>${esc(m.naam)}</th></tr></thead><tbody>
    ${row("Stamboek",esc(s.stamboek||"onbekend"),esc(m.stamboek||"onbekend"))}
    ${row("Geboortejaar",esc(s.geboortejaar||"onbekend"),esc(m.geboortejaar||"onbekend"))}
    ${row("Vader",esc(s.stamboom&&s.stamboom.v||"onbekend"),esc(m.stamboom&&m.stamboom.v||"onbekend"))}
    ${row("Moedersvader",esc(s.stamboom&&s.stamboom.mv||"onbekend"),esc(m.stamboom&&m.stamboom.mv||"onbekend"))}
    ${row("Bloedpercentage",bloodHtml(bloodOf(s)),bloodHtml(bloodOf(m)))}
    ${row("Stokmaat",num(s.stokmaat_cm)!=null?esc(s.stokmaat_cm)+" cm":"onbekend",num(m.stokmaat_cm)!=null?esc(m.stokmaat_cm)+" cm":"onbekend")}
    ${row("Hoogste niveau",fmtH(s.hoogste_niveau_cm),fmtH(m.hoogste_niveau_cm))}
    ${row("Nakomelingen<br><span class='small'>sport / 1m40+ / 1m50+</span>",nk(s),nk(m))}
    ${row("Fokwaarden",fokHtml(s),fokHtml(m))}
    ${row("Fokwaarde genormaliseerd",zz(s),zz(m))}
    ${row("Gezondheid",wffsChip(s.wffs)+" "+ocdChip(s),wffsChip(m.wffs)+" "+ocdChip(m))}
    ${row("Datavolledigheid",Math.round(completeOf(s))+"%",Math.round(completeOf(m))+"%")}
    ${row("Bronnen",srcHtml(s),srcHtml(m))}
   </tbody></table></div>
   <div class="card">
    <div class="label">Combinatie</div><h2>${esc(s.naam)} x ${esc(m.naam)}</h2>
    <div class="score" style="margin-top:10px"><span class="big num">${r.excluded?"&ndash;":Math.round(r.total)}</span><span class="muted">/ 100</span>
     ${r.excluded?'<span class="chip bad">Uitgesloten</span>':`<span class="chip">Betrouwbaarheid ${r.conf}</span>`}</div>
    <div class="row" style="margin-top:10px;gap:8px;align-items:center"><button type="button" class="btn" id="fokPdf">Fokadvies als PDF</button>${stalAan()?'<button type="button" class="btn ghost" id="vvBewaar">Bewaar in Mijn veulens</button>':""}<span class="status small" id="fokPdfSt" role="status"></span></div>
    ${warnHtml(r)}${compHtml(r)}
    ${r.reasons.length?`<h3 style="margin-top:16px">Sterke punten</h3><ul class="plain">${r.reasons.map(x=>`<li>${esc(x)}</li>`).join("")}</ul>`:""}
    ${r.weak.length?`<h3 style="margin-top:12px">Aandachtspunten</h3><ul class="plain">${r.weak.map(x=>`<li>${esc(x)}</li>`).join("")}</ul>`:""}
    ${coiHtml(r.coi)}
    <p class="small muted" style="margin-top:12px">Deze score is een hulpmiddel en vervangt geen advies van stamboek, dierenarts of fokker.</p>
   </div></div>${(()=>{const f=foalOf(s,m);state.cmpFoal=f;return `<section class="card pc-foal"><div class="label">Stamboom van het veulen</div><h3 style="margin:2px 0 0">${esc(s.naam)} x ${esc(m.naam)}</h3>${foalFactsHtml(s,m)}<div class="pc-wrap">${pedCardSlot(f)}</div></section>`})()}`;renderCouncil(s,m);requestAnimationFrame(paintPedSlots);fillFoalKin(s,m);ensureStal();stalKnopCmp()}

// ---------- Paarden beheren: werkplek van een Fokwijzer-profiel ----------
// Tabbladen: Mijn stal (stal), Mijn veulens (veulens), Paard toevoegen (aanvragen = automatisch, beheer = zelf invullen).
const WERK=["stal","veulens","aanvragen","beheer"];
function subtabsHtml(t){const toev=t==="aanvragen"||t==="beheer";const sel=(k)=>`aria-selected="${k}"`;
  const top=`<div class="subtabs" role="tablist" aria-label="Paarden beheren"><button type="button" role="tab" data-sub="stal" ${sel(t==="stal")}>Mijn stal</button><button type="button" role="tab" data-sub="veulens" ${sel(t==="veulens")}>Mijn veulens</button><button type="button" role="tab" data-sub="toevoegen" ${sel(toev)}>Paard toevoegen <span class="count-badge" data-subbadge${$("reqBadge").hidden?" hidden":""}>${esc($("reqBadge").textContent)}</span></button></div>`;
  return top+(toev?`<div class="subtabs sub2" role="tablist" aria-label="Paard toevoegen"><button type="button" role="tab" data-sub="aanvragen" ${sel(t==="aanvragen")}>Automatisch laten opzoeken</button><button type="button" role="tab" data-sub="beheer" ${sel(t==="beheer")}>Zelf invullen</button></div>
    <p class="small muted sub2-uitleg">${t==="aanvragen"?"Geef de naam (en eventueel een link of printscreen): de data-agent zoekt afstamming, sport, gezondheid en identiteit op en zet alles klaar om na te kijken.":"Vul zelf de gegevens van een paard in, of pas een paard aan dat je eerder toevoegde."}</p>`:"")}
// Opslag: per persoon één privé-document {hengsten:[id], merries:[id], veulens:[{id,s,m,naam,notitie,gemaakt_op}]}.
const STAL_MAX=300,VEUL_MAX=200;
state.stal={hengsten:[],merries:[],veulens:[]};state.stalOk=false;let stalSub=null,stalKey="";
function stalRef(){return state.site?db.doc("mijnstal/"+state.meId):db.collection("data/users/"+state.meId).doc("stal")}
function stalAan(){return !!(db&&state.canWrite&&state.meId&&state.dbState==="ready")}
function ensureStal(){const k=stalAan()?state.meId:"";if(k===stalKey)return;stalKey=k;if(stalSub){try{stalSub()}catch(_){}stalSub=null}
  state.stal={hengsten:[],merries:[],veulens:[]};state.stalOk=false;if(!k)return;
  try{stalSub=stalRef().onSnapshot(d=>{const v=d&&d.exists?d.data():null;state.stal={naam:(v&&typeof v.naam==="string"?v.naam:""),hengsten:(v&&v.hengsten)||[],merries:(v&&v.merries)||[],veulens:(v&&v.veulens)||[]};state.stalOk=true;
    if(state.tab==="stal")renderStal();if(state.tab==="veulens")renderVeulens();if(state.tab==="vergelijken")stalKnopCmp();if(state.tab==="zoeken")stalKnopDet()},err=>{state.stalOk=true;state.stalErr=true;if(state.tab==="stal")renderStal()})}catch(_){state.stalOk=true;state.stalErr=true}}
let stalBusy=Promise.resolve();
function stalSave(fn,st){ // fn past een kopie aan; daarna in volgorde bewaren
  const nw=JSON.parse(JSON.stringify(state.stal));fn(nw);nw.hengsten=[...new Set(nw.hengsten)].slice(0,STAL_MAX);nw.merries=[...new Set(nw.merries)].slice(0,STAL_MAX);nw.veulens=nw.veulens.slice(0,VEUL_MAX);nw.bijgewerkt=new Date().toISOString();
  state.stal=nw;if(state.tab==="stal")renderStal();if(state.tab==="veulens")renderVeulens();stalKnopDet();stalKnopCmp();
  stalBusy=stalBusy.then(()=>stalRef().set(clean(nw))).then(()=>{if(st){st.className="status ok";st.textContent="Bewaard."}}).catch(err=>{const m="Bewaren lukte niet: "+(err&&err.message||"onbekende fout");if(st){st.className="status err";st.textContent=m}else fwToast(m)});return stalBusy}
function fwToast(t){const d=document.createElement("div");d.className="sim-toast";d.setAttribute("role","status");d.textContent=t;document.body.appendChild(d);setTimeout(()=>d.remove(),4500)}
const eigenPaarden=()=>state.meId?state.horses.filter(h=>h.eigenaar_id!=null&&String(h.eigenaar_id)===state.meId):[];
const inStal=(h)=>!!h&&((h.geslacht==="merrie"?state.stal.merries:state.stal.hengsten).includes(h.id)||(state.meId&&h.eigenaar_id!=null&&String(h.eigenaar_id)===state.meId));
function stalLijst(g){const ids=g==="hengst"?state.stal.hengsten:state.stal.merries;const out=ids.map(byId).filter(h=>h&&h.geslacht===g);
  eigenPaarden().filter(h=>h.geslacht===g&&!ids.includes(h.id)).forEach(h=>out.push(h));return out.sort((a,b)=>String(a.naam).localeCompare(String(b.naam)))}
function stalToggle(h,st){if(!h||!stalAan())return;const k=h.geslacht==="merrie"?"merries":"hengsten";const weg=state.stal[k].includes(h.id);
  return stalSave(v=>{v[k]=weg?v[k].filter(x=>x!==h.id):v[k].concat([h.id])},st)}
function geenWerkplek(){if(state.dbState==="loading")return '<p class="small muted">Opslag wordt geladen...</p>';
  if(state.dbState==="none")return '<div class="banner"><strong>Opslag niet beschikbaar.</strong> In deze weergave kan niets bewaard worden.</div>';
  const rol=state.site?state.rol||"anoniem":(state.platformWrite?state.rol:"lezer");
  const uitleg='<div class="card werk-uitleg"><h3 style="margin:0">Je eigen Fokwijzer</h3><p style="margin:6px 0 0">Met een <b>Fokwijzer-profiel</b> bewaar je hengsten en merries in <b>Mijn stal</b>, combineer je ze, maak en bewaar je <b>virtuele veulens</b> met een fokadvies als PDF, en voeg je paarden toe: automatisch laten opzoeken of zelf invullen.</p></div>';
  if(state.site||state.platformWrite)return uitleg+pbCta(rol);
  return uitleg+'<div class="banner"><strong>Alleen lezen.</strong> Vraag de eigenaar om de rechten van een Fokwijzer-profiel.</div>'}
const stalRegel=(h)=>{const sb=h.stamboom||{};const d=dekOf(h),b=d&&BESCHIK[d.beschikbaar];const eigen=state.meId&&h.eigenaar_id!=null&&String(h.eigenaar_id)===state.meId;
  return `<li class="stal-item"><div class="stal-naam"><button type="button" class="linkbtn" data-stalopen="${esc(h.id)}">${esc(h.naam)}</button>
    <div class="small muted">${[h.geboortejaar,(sb.v||"?")+" x "+(sb.mv||"?")].filter(Boolean).map(esc).join(" · ")}</div>
    <div class="chips" style="margin-top:3px">${eigen?'<span class="chip">Eigen paard</span>':""}${h.wffs&&h.wffs!=="onbekend"?wffsChip(h.wffs):""}${num(h.hoogste_niveau_cm)!=null?`<span class="chip">${esc(fmtH(h.hoogste_niveau_cm))}</span>`:""}${b?`<span class="chip ${b[1]}">${b[0]}</span>`:""}</div></div>
    <div class="stal-acties">${h.geslacht==="merrie"?`<button type="button" class="btn ghost" data-stalcomb="${esc(h.id)}">Combineer</button>`:""}${eigen?"":`<button type="button" class="hc-del" data-staldel="${esc(h.id)}" aria-label="${esc(h.naam)} uit je stal halen" title="Uit je stal halen">&times;</button>`}</div></li>`};
function renderStal(){const out=$("stalOut");if(!out)return;ensureStal();
  if(!stalAan()){out.innerHTML=geenWerkplek();return}
  if(!state.stalOk){out.innerHTML='<p class="small muted">Je stal wordt geladen...</p>';return}
  const H=stalLijst("hengst"),M=stalLijst("merrie");
  const kol=(g,lijst,titel)=>`<section class="card stal-kol"><h3 style="margin:0 0 8px">${titel} <span class="muted small">(${lijst.length})</span></h3>
    <div class="stal-add"><label class="label" for="stalZoek-${g}">${g==="hengst"?"Hengst toevoegen":"Merrie toevoegen"}</label><input id="stalZoek-${g}" type="search" autocomplete="off" data-stalzoek="${g}" placeholder="Naam van ${g==="hengst"?"de hengst":"de merrie"}"><div class="stal-sug" data-stalsug="${g}"></div></div>
    ${lijst.length?`<ul class="stal-list">${lijst.map(stalRegel).join("")}</ul>`:`<p class="small muted" style="margin:10px 0 0">${g==="hengst"?"Nog geen hengsten in je stal. Zoek hierboven of klik bij een hengst op In mijn stal. De hengst hoeft niet per se je eigendom te zijn: je kunt hem perfect als voorkeurhengst toevoegen aan je stal op De Fokwijzer.":"Nog geen merries in je stal. Zoek hierboven of klik bij een merrie op In mijn stal. De merrie hoeft niet per se je eigendom te zijn: je kunt haar perfect als voorkeurmerrie toevoegen aan je stal op De Fokwijzer."}</p>`}</section>`;
  const mSel=M.some(m=>m.id===state.stalM)?state.stalM:(M[0]&&M[0].id)||"";state.stalM=mSel;
  const sn=state.stal.naam||"";
  out.innerHTML=`${state.stalErr?'<div class="status err">Je stal kon niet geladen worden.</div>':""}
   <div class="stal-titel"><div style="min-width:0"><div class="label">Mijn stal</div><h2 class="stal-naam-h">${sn?esc(sn):'<span class="muted">Geef je stal een naam</span>'}</h2></div><button type="button" class="btn ghost" data-stalnaam>${sn?"Naam aanpassen":"Naam geven"}</button></div>
   <form class="stal-naam-form" id="stalNaamForm" hidden><div class="field grow"><label class="label" for="stalNaam">Naam van je stal</label><input id="stalNaam" maxlength="80" value="${esc(sn)}" placeholder="bv. Stoeterij De Linde"></div><button class="btn" type="submit">Bewaren</button><button class="btn ghost" type="button" data-stalnaamweg>Annuleren</button></form>
   <div class="stal-grid">${kol("hengst",H,"Hengsten")}${kol("merrie",M,"Merries")}</div>
   <section class="card" style="margin-top:14px" id="stalCombCard"><h3 style="margin:0">Combineren</h3>
    ${M.length?`<p class="small muted" style="margin:4px 0 10px">Kies een merrie: de hengsten uit je stal worden gerangschikt op hoe goed ze bij haar passen.</p>
     <div class="row"><div class="field grow"><label class="label" for="stalM">Merrie</label><select id="stalM">${M.map(m=>`<option value="${esc(m.id)}"${m.id===mSel?" selected":""}>${esc(m.naam)}${m.geboortejaar?" ("+esc(m.geboortejaar)+")":""}</option>`).join("")}</select></div></div>
     <div id="stalComb" style="margin-top:12px"></div>`:'<p class="small muted" style="margin:4px 0 0">Voeg een merrie toe aan je stal om je hengsten met haar te combineren.</p>'}
    <div class="status" id="stalSt" role="status"></div></section>`;
  if(M.length)renderComb()}
// Combineren: je eigen hengsten voor deze merrie, en daaronder de beste hengsten uit de hele database.
let _combC={src:null,map:new Map()};
function combRij(r,m,i,extra){const bew=state.stal.veulens.some(v=>v.s===r.s.id&&v.m===m.id);
  return `<div class="comb-row"><span class="rank num">${r.excluded?"&ndash;":i+1}</span>
     <span style="min-width:0"><b>${esc(r.s.naam)}</b> <span class="small muted">x ${esc(m.naam)}</span>
      <span class="chips" style="margin-top:4px"><span class="chip">inteelt ${pct(r.coi.F)}</span>${r.excluded?'<span class="chip bad">Uitgesloten</span>':`<span class="chip">betrouwbaarheid ${esc(r.conf)}</span>`}${r.warnings.map(w=>`<span class="chip ${w.lvl}">${esc(w.t)}</span>`).join("")}</span>
      ${r.excluded?"":`<div class="minibar"><div class="fill" style="width:${r.total}%"></div></div>`}</span>
     <span class="mscore num">${r.excluded?"&ndash;":Math.round(r.total)}</span>
     <span class="comb-acties">${extra?`<button type="button" class="btn ghost" data-staladd="${esc(r.s.id)}">+ In mijn stal</button>`:""}<button type="button" class="btn ghost" data-vvopen="${esc(r.s.id)}|${esc(m.id)}">Virtueel veulen</button><button type="button" class="btn${bew?" ghost":""}" data-vvbewaar="${esc(r.s.id)}|${esc(m.id)}"${bew?" disabled":""}>${bew?"Bewaard":"Bewaar veulen"}</button></span></div>`}
function renderComb(){const box=$("stalComb");if(!box)return;const m=byId(state.stalM);if(!m){box.innerHTML="";return}
  const H=stalLijst("hengst"),mijn=new Set(H.map(h=>h.id));
  const rs=H.map(s=>match(s,m)).sort((a,b)=>(a.excluded-b.excluded)||(b.total-a.total));const ok=rs.filter(r=>!r.excluded);
  box.innerHTML=`${H.length?`<div class="label" style="margin-bottom:6px">Hengsten uit je stal</div><div class="list">${rs.map((r,i)=>combRij(r,m,i,false)).join("")}</div>
     ${ok.length>=2?`<button type="button" class="btn ghost" data-stalhc="${esc(ok.slice(0,4).map(r=>r.s.id).join(","))}" data-m="${esc(m.id)}" style="margin-top:10px">Vergelijk de beste ${Math.min(4,ok.length)} hengsten naast elkaar</button>`:""}`
    :'<p class="small muted" style="margin:0">Je hebt nog geen hengsten in je stal. Hieronder staan de best passende hengsten uit de hele database: zet ze met één klik in je stal.</p>'}
   <div class="label" style="margin:16px 0 6px">Beste hengsten uit de hele database</div><div id="combAlle"><p class="small muted">Wordt berekend...</p></div>`;
  if(_combC.src!==state.horses)_combC={src:state.horses,map:new Map()};
  const toon=(lijst)=>{const el=$("combAlle");if(!el||state.stalM!==m.id)return;const top=lijst.filter(r=>!mijn.has(r.s.id)).slice(0,5);
    el.innerHTML=top.length?`<div class="list">${top.map((r,i)=>combRij(r,m,i,true)).join("")}</div><button type="button" class="linkbtn" data-stalmatch="${esc(m.id)}" style="margin-top:8px">Alle beste matches voor ${esc(m.naam)} bekijken</button>`:'<p class="small muted">Geen andere hengsten gevonden.</p>'};
  if(_combC.map.has(m.id)){toon(_combC.map.get(m.id));return}
  setTimeout(()=>{if(state.stalM!==m.id||!$("combAlle"))return;const lijst=state.horses.filter(h=>h.geslacht==="hengst"&&!h.ruin).map(s=>match(s,m)).filter(r=>!r.excluded).sort((a,b)=>b.total-a.total).slice(0,40);
    _combC.map.set(m.id,lijst);toon(lijst)},30)}
function stalSug(inp){const g=inp.dataset.stalzoek,box=document.querySelector(`[data-stalsug="${g}"]`);if(!box)return;const q=norm(inp.value);
  if(q.length<2){box.innerHTML="";return}
  const have=new Set(stalLijst(g).map(h=>h.id));
  const hits=state.horses.filter(h=>h.geslacht===g&&!have.has(h.id)&&(norm(h.naam).includes(q)||(h.naam_varianten||[]).some(v=>norm(v).includes(q)))).sort((a,b)=>(norm(a.naam).startsWith(q)?0:1)-(norm(b.naam).startsWith(q)?0:1)||String(a.naam).localeCompare(String(b.naam))).slice(0,8);
  box.innerHTML=hits.length?hits.map(h=>`<button type="button" class="stal-sug-i" data-staladd="${esc(h.id)}"><b>${esc(h.naam)}</b> <span class="small muted">${[h.geboortejaar,(h.stamboom&&h.stamboom.v||"?")+" x "+(h.stamboom&&h.stamboom.mv||"?")].filter(Boolean).map(esc).join(" · ")}</span></button>`).join("")
    :`<div class="small muted stal-geen">Niet gevonden in de database. <button type="button" class="linkbtn" data-stalvraag="${esc(inp.value.trim())}">Laat het automatisch opzoeken</button></div>`}
// ---------- Mijn veulens ----------
const vvId=()=>"v"+Date.now().toString(36)+Math.random().toString(36).slice(2,6);
function vvBewaar(sId,mId,naam,st){const s=byId(sId),m=byId(mId);if(!s||!m||!stalAan())return;
  if(state.stal.veulens.some(v=>v.s===sId&&v.m===mId)){if(st){st.className="status ok";st.textContent="Dit veulen is al bewaard."}return}
  if(state.stal.veulens.length>=VEUL_MAX){if(st){st.className="status err";st.textContent=`Je kunt maximaal ${VEUL_MAX} veulens bewaren.`}return}
  return stalSave(v=>{v.veulens.unshift({id:vvId(),s:sId,m:mId,s_naam:s.naam,m_naam:m.naam,naam:(naam||"").slice(0,80),notitie:"",gemaakt_op:new Date().toISOString()});
    // de ouders komen ook in je stal
    if(!v.hengsten.includes(sId)&&!(s.eigenaar_id!=null&&String(s.eigenaar_id)===state.meId))v.hengsten.push(sId);if(!v.merries.includes(mId)&&!(m.eigenaar_id!=null&&String(m.eigenaar_id)===state.meId))v.merries.push(mId)},st)}
function renderVeulens(){const out=$("veulOut");if(!out)return;ensureStal();
  if(!stalAan()){out.innerHTML=geenWerkplek();return}
  if(!state.stalOk){out.innerHTML='<p class="small muted">Je veulens worden geladen...</p>';return}
  const H=stalLijst("hengst"),M=stalLijst("merrie");const sorted=[...state.horses].sort((a,b)=>String(a.naam).localeCompare(String(b.naam)));
  const opts=(g,mijn)=>{const ids=new Set(mijn.map(h=>h.id));const o=(h)=>`<option value="${esc(h.id)}">${esc(h.naam)}${h.geboortejaar?" ("+esc(h.geboortejaar)+")":""}</option>`;
    return `<option value="">${g==="hengst"?"Kies een hengst":"Kies een merrie"}</option>${mijn.length?`<optgroup label="Mijn stal">${mijn.map(o).join("")}</optgroup>`:""}<optgroup label="${g==="hengst"?"Alle hengsten":"Alle merries"}">${sorted.filter(h=>h.geslacht===g&&!h.ruin&&!ids.has(h.id)).map(o).join("")}</optgroup>`};
  const V=state.stal.veulens;
  out.innerHTML=`<section class="card vv-new"><h3 style="margin:0">Nieuw virtueel veulen</h3><p class="small muted" style="margin:4px 0 10px">Kies een hengst en een merrie (eerst die uit je stal). Je kunt het veulen een naam geven, bv. het jaar of een plan.</p>
    <div class="row"><div class="field grow"><label class="label" for="vvS">Hengst</label><select id="vvS">${opts("hengst",H)}</select></div><div class="field grow"><label class="label" for="vvM">Merrie</label><select id="vvM">${opts("merrie",M)}</select></div>
    <div class="field grow"><label class="label" for="vvNaam">Naam (optioneel)</label><input id="vvNaam" maxlength="80" placeholder="bv. Veulen 2027"></div><button type="button" class="btn" id="vvMaak">Maak en bewaar</button></div>
    <div class="status" id="vvSt" role="status"></div></section>
   <h3 style="margin:18px 0 8px">Mijn veulens <span class="muted small">(${V.length})</span></h3>
   ${V.length?`<div class="vv-grid">${V.map(vvKaart).join("")}</div>`:'<div class="card empty">Nog geen veulens bewaard. Maak er hierboven een, of bewaar er een bij Virtueel veulen of bij Combineren in Mijn stal.</div>'}`}
function vvKaart(v){const s=byId(v.s),m=byId(v.m);const titel=v.naam||`${s?s.naam:v.s_naam||"?"} x ${m?m.naam:v.m_naam||"?"}`;
  const kop=`<div class="vv-kop"><div style="min-width:0"><div class="label">${v.naam?esc((s?s.naam:v.s_naam||"?")+" x "+(m?m.naam:v.m_naam||"?")):"Virtueel veulen"}</div><h3 class="vv-titel">${esc(titel)}</h3></div>`;
  if(!s||!m)return `<article class="card vv-kaart">${kop}</div><p class="small muted">Een van de ouders staat niet meer in de database.</p><div class="row"><button type="button" class="btn danger" data-vvweg="${esc(v.id)}">Weghalen</button></div></article>`;
  const r=match(s,m);
  return `<article class="card vv-kaart">${kop}<div class="vv-score"><span class="big num">${r.excluded?"&ndash;":Math.round(r.total)}</span><span class="muted small">/ 100</span></div></div>
   <div class="chips" style="margin:6px 0"><span class="chip">inteelt ${pct(r.coi.F)}</span>${r.excluded?'<span class="chip bad">Uitgesloten</span>':`<span class="chip">betrouwbaarheid ${esc(r.conf)}</span>`}${r.warnings.map(w=>`<span class="chip ${w.lvl}">${esc(w.t)}</span>`).join("")}</div>
   ${v.notitie?`<p class="vv-notitie">${esc(v.notitie)}</p>`:""}
   <p class="small muted" style="margin:4px 0 8px"><span>Bewaard op</span> <span>${esc(dagTxt(v.gemaakt_op))}</span></p>
   <div class="row vv-acties"><button type="button" class="btn ghost" data-vvopen="${esc(v.s)}|${esc(v.m)}">Bekijken</button><button type="button" class="btn ghost" data-vvpdf="${esc(v.id)}">Fokadvies als PDF</button><button type="button" class="btn ghost" data-vvedit="${esc(v.id)}">Naam en notitie</button><button type="button" class="btn danger" data-vvweg="${esc(v.id)}">Weghalen</button></div>
   <form class="vv-form" data-vvform="${esc(v.id)}" hidden><div class="field"><label class="label" for="vvn-${esc(v.id)}">Naam</label><input id="vvn-${esc(v.id)}" maxlength="80" value="${esc(v.naam||"")}"></div><div class="field" style="margin-top:6px"><label class="label" for="vvt-${esc(v.id)}">Notitie</label><textarea id="vvt-${esc(v.id)}" rows="3" maxlength="1000">${esc(v.notitie||"")}</textarea></div><div class="row" style="margin-top:6px"><button class="btn" type="submit">Bewaren</button></div></form>
   <div class="status" data-vvst="${esc(v.id)}" role="status"></div></article>`}
// Knoppen elders: bij een paard (In mijn stal) en bij Virtueel veulen (Bewaar in Mijn veulens).
function stalKnopDet(){const b=document.querySelector('#detail [data-act="stal"]');if(!b)return;const h=byId(b.dataset.id);const ja=inStal(h);b.textContent=ja?"In je stal ✓":"In mijn stal";b.classList.toggle("ghost",!ja||true);b.setAttribute("aria-pressed",String(ja));
  const eigen=h&&state.meId&&h.eigenaar_id!=null&&String(h.eigenaar_id)===state.meId;b.disabled=!!eigen;if(eigen)b.title="Eigen paarden staan altijd in je stal."}
function stalKnopCmp(){const b=$("vvBewaar");if(!b)return;const s=$("cS").value,m=$("cM").value;const ja=state.stal.veulens.some(v=>v.s===s&&v.m===m);b.textContent=ja?"Bewaard in Mijn veulens ✓":"Bewaar in Mijn veulens";b.disabled=ja}
// ---------- hengsten naast elkaar ----------
function renderHengsten(){const out=$("hcOut");if(!out)return;
  const hs=[...new Set([0,1,2,3].map(i=>$("hc"+i).value).filter(Boolean))].map(byId).filter(Boolean),m=byId($("hcM").value);
  if(hs.length<2){out.innerHTML='<div class="card empty">Kies minstens twee hengsten om ze naast elkaar te zetten.</div>';return}
  const rs=m?hs.map(s=>match(s,m)):null,n=hs.length,o=(h)=>h.nakomelingen||{},unk='<span class="muted">onbekend</span>';
  // de beste waarde in een rij krijgt een groene achtergrond (alleen als niet alle waarden gelijk zijn)
  const row=(l,cells,vals,low)=>{let b=null;if(vals){const v=vals.filter(x=>x!=null);if(v.length>=2){const x=low?Math.min(...v):Math.max(...v);if(v.some(y=>y!==x))b=x}}
    return `<tr><th scope="row">${l}</th>${cells.map((c,i)=>`<td${b!=null&&vals[i]===b?' class="hc-best"':""}>${c}</td>`).join("")}</tr>`};
  const sec=(t)=>`<tr class="hc-sec"><th scope="colgroup" colspan="${n+1}">${t}</th></tr>`;
  const map=(f)=>hs.map(f);
  const nk=(h)=>num(o(h).sport)!=null?`<span class="num">${esc(o(h).sport)}</span> / <span class="num">${esc(o(h).m140||0)}</span> / <span class="num">${esc(o(h).m150||0)}</span>`:unk;
  const dk=(h,f)=>{const d=dekOf(h);const v=d&&f(d);return v||unk};
  out.innerHTML=`<div class="tablewrap hc-wrap"><table class="hc-tab" style="--hc-n:${n}"><thead><tr><th scope="col"><span class="sr-only">Gegeven</span></th>${hs.map((h,i)=>`<th scope="col"><div class="hc-head"><button type="button" class="hc-name" data-hcopen="${esc(h.id)}" title="Details bekijken">${esc(h.naam)}</button><button type="button" class="hc-del" data-hcdel="${[0,1,2,3].find(k=>$("hc"+k).value===h.id)}" aria-label="${esc(h.naam)} weghalen" title="Weghalen">&times;</button></div><div class="small muted hc-sub">${esc(h.stamboom&&h.stamboom.v||"?")} x ${esc(h.stamboom&&h.stamboom.mv||"?")}</div></th>`).join("")}</tr></thead><tbody>
   ${sec("Paard")}
   ${row("Stamboek",map(h=>esc(h.stamboek||"onbekend")))}
   ${row("Geboortejaar",map(h=>esc(h.geboortejaar||"onbekend")))}
   ${row("Stokmaat",map(h=>num(h.stokmaat_cm)!=null?esc(h.stokmaat_cm)+" cm":unk))}
   ${row("Hoogste niveau",map(h=>fmtH(h.hoogste_niveau_cm)),map(h=>num(h.hoogste_niveau_cm)))}
   ${row("Nakomelingen<br><span class='small'>sport / 1m40+ / 1m50+</span>",map(nk),map(h=>num(o(h).m140)))}
   ${row("Fokwaarden",map(fokHtml))}
   ${row("Fokwaarde genormaliseerd",map(h=>{const z=zOf(h);return z==null?unk:`<span class="num">${fz(z,2)}</span> SD`}),map(zOf))}
   ${row("Bloedpercentage",map(h=>bloodHtml(bloodOf(h))))}
   ${row("Gezondheid",map(h=>wffsChip(h.wffs)+" "+ocdChip(h)))}
   ${row("Datavolledigheid",map(h=>Math.round(completeOf(h))+"%"),map(h=>Math.round(completeOf(h))))}
   ${sec("Dekinfo")}
   ${row("Dekgeld",map(h=>dk(h,d=>d.dekgeld&&esc(d.dekgeld))))}
   ${row("Sperma",map(h=>dk(h,d=>spermaTxt(d).map(esc).join("<br>"))))}
   ${row("Beschikbaarheid",map(h=>dk(h,d=>{const b=BESCHIK[d.beschikbaar];return (b?`<span class="chip ${b[1]}">${b[0]}</span>`:"")+(d.seizoen?` <span class="small muted">dekseizoen ${esc(d.seizoen)}</span>`:"")+(d.toelichting?`<div class="small">${esc(d.toelichting)}</div>`:"")})))}
   ${row("Station",map(h=>{const d=dekOf(h);return d&&(d.station||okUrl(d.url))?stationHtml(d):unk}))}
   ${m?`${sec(`<span>Combinatie met</span> <span>${esc(m.naam)}</span>`)}
   ${row("Score",rs.map(r=>r.excluded?'<span class="chip bad">Uitgesloten</span>':`<span class="num hc-score">${Math.round(r.total)}</span> <span class="muted small">/ 100</span>`),rs.map(r=>r.excluded?null:Math.round(r.total)))}
   ${row("Betrouwbaarheid",rs.map(r=>esc(r.conf)))}
   ${row("Inteelt van het veulen",rs.map(r=>`<span class="num">${pct(r.coi.F)}</span>`),rs.map(r=>Math.round(r.coi.F*1e5)),true)}
   ${row("Waarschuwingen",rs.map(r=>r.warnings.length?r.warnings.map(w=>`<span class="chip ${w.lvl}">${esc(w.t)}</span>`).join(" "):'<span class="muted">geen</span>'))}
   ${row("Sterke punten",rs.map(r=>r.reasons.length?`<ul class="plain small">${r.reasons.slice(0,4).map(x=>`<li>${esc(x)}</li>`).join("")}</ul>`:'<span class="muted">geen</span>'))}
   ${row("",rs.map(r=>`<button type="button" class="btn ghost hc-vv" data-hcvv="${esc(r.s.id)}">Virtueel veulen</button>`))}`:""}
  </tbody></table></div>
  <p class="small muted" style="margin-top:10px">Groen gemarkeerd: de beste waarde in die rij. ${m?"":"Kies een merrie om de combinaties te scoren. "}Dekinfo kan veranderen: controleer ze altijd bij het station.</p>`}
function renderMatches(){["gen","perf","coi","health","data"].forEach(k=>{$("w-"+k).value=state.w[k];$("wv-"+k).textContent=state.w[k]});$("tWarn").value=state.t.warn;$("tMax").value=state.t.max;
  const h=byId($("mFor").value);if(!h){$("matchOut").innerHTML='<div class="card empty">Kies een hengst of merrie om de best passende partners te zien.</div>';return}
  const cands=state.horses.filter(x=>x.geslacht!==h.geslacht&&x.id!==h.id&&!x.ruin);
  if(!cands.length){$("matchOut").innerHTML=`<div class="card empty">Er staan nog geen ${h.geslacht==="hengst"?"merries":"hengsten"} in de database.</div>`;return}
  const res=cands.map(c=>h.geslacht==="hengst"?match(h,c):match(c,h));
  const ok=res.filter(r=>!r.excluded).sort((a,b)=>b.total-a.total),bad=res.filter(r=>r.excluded);
  const other=(r)=>h.geslacht==="hengst"?r.m:r.s;
  const line=(r,i)=>{const p=other(r);return `<button class="match" type="button" data-s="${esc(r.s.id)}" data-m="${esc(r.m.id)}"><span class="rank num">${i==null?"&ndash;":i+1}</span>
    <span style="min-width:0"><b>${esc(p.naam)}</b> <span class="small muted">${esc(p.stamboom&&p.stamboom.v||"?")} x ${esc(p.stamboom&&p.stamboom.mv||"?")}</span>
     <span class="chips" style="margin-top:4px"><span class="chip">inteelt ${pct(r.coi.F)}</span>${r.excluded?"":`<span class="chip">betrouwbaarheid ${r.conf}</span>`}${r.warnings.map(w=>`<span class="chip ${w.lvl}">${esc(w.t)}</span>`).join("")}</span>
     ${r.reasons.length?`<span class="small muted" style="display:block;margin-top:4px">${esc(r.reasons.slice(0,3).join(", "))}</span>`:""}
     ${r.excluded?"":`<div class="minibar"><div class="fill" style="width:${r.total}%"></div></div>`}</span>
    <span class="mscore num">${r.excluded?"&ndash;":Math.round(r.total)}</span></button>`};
  $("matchOut").innerHTML=`<div class="label" style="margin-bottom:6px">Beste ${h.geslacht==="hengst"?"merries":"hengsten"} voor ${esc(h.naam)}</div>
   ${h.geslacht==="merrie"&&ok.length>=2?`<button type="button" class="btn ghost" id="mTop4" data-ids="${esc(ok.slice(0,4).map(r=>r.s.id).join(","))}" data-m="${esc(h.id)}" style="margin:0 0 10px">Vergelijk de beste ${Math.min(4,ok.length)} hengsten naast elkaar</button>`:""}
   <div class="list">${ok.length?ok.slice(0,15).map((r,i)=>line(r,i)).join(""):'<div class="empty">Alle combinaties zijn uitgesloten.</div>'}</div>
   ${bad.length?`<details class="card" style="margin-top:14px"><summary>Uitgesloten combinaties (${bad.length})</summary><div class="list" style="margin-top:10px">${bad.map(r=>line(r,null)).join("")}</div></details>`:""}
   <p class="small muted" style="margin-top:12px">Klik op een combinatie om ze naast elkaar te zetten. De score is een hulpmiddel en vervangt geen advies van stamboek, dierenarts of fokker.</p>`}

