function buildPedInputs(){$("pedInputs").innerHTML=PED_KEYS.map(k=>`<div class="field"><label class="label" for="ped-${k}">${PED_LABEL[k]||k.toUpperCase()}</label><input id="ped-${k}"></div>`).join("")}
function renderBeheer(){let note="";
  if(state.dbState==="none")note='<div class="banner"><strong>Opslag niet beschikbaar.</strong> Log in om bij te dragen.</div>';
  else if(state.dbState==="loading")note='<p class="small muted">Opslag wordt geladen...</p>';
  else if(!state.canWrite)note='<div class="banner"><strong>Alleen lezen.</strong> Je hebt geen rechten om paarden toe te voegen of te wijzigen. Log in met een Fokwijzer-profiel, of vraag die rol aan bij Account maken.</div>';
  // Op de website: zonder de juiste rol eerst een account (of de rol Fokwijzer-profiel) nemen.
  const rol=state.site?state.rol||"anoniem":(state.platformWrite?state.rol:"lezer");const site=state.site||state.dbState==="ready";
  if(site&&!state.canWrite&&!(state.site===false&&!state.platformWrite)){
    note=pbCta(rol)}
  $("writeNote").innerHTML=note;const dis=!state.canWrite;["saveBtn","impBtn","lnkBtn"].forEach(id=>$(id).disabled=dis);
  if(!state.site&&state.dbState==="ready"&&!state.platformWrite)note='<div class="banner"><strong>Alleen lezen.</strong> Je mag deze Fokwijzer bekijken maar niet bewerken. Vraag de eigenaar om bewerkrechten (Kan bewerken) als je wilt bijdragen.</div>';
  $("writeNote").innerHTML=note;
  renderBeheerRest(site)}
function pbCta(rol){return rol==="anoniem"
      ?`<div class="card pb-cta"><h3 style="margin:0">Je eigen paarden beheren</h3><p style="margin:6px 0 12px">Voeg je eigen paarden toe en houd hun gegevens bij. Daarvoor maak je eerst een gratis account met een <b>Fokwijzer-profiel</b>. Je kunt meteen aan de slag.</p><div class="row"><button class="btn" type="button" data-acct="registreren-pb">Account maken met een Fokwijzer-profiel</button><button class="btn ghost" type="button" data-acct="inloggen">Ik heb al een account: inloggen</button></div></div>`
      :`<div class="card pb-cta"><h3 style="margin:0">Maak je Fokwijzer-profiel</h3><p style="margin:6px 0 12px">Je bent ingelogd als <b>bijdrager</b>. Met een Fokwijzer-profiel voeg je je eigen paarden toe en pas je gegevens aan. Dat kan meteen, zonder goedkeuring.</p><div class="row"><button class="btn" type="button" data-acct="word-pb">Maak je Fokwijzer-profiel</button></div><div class="status" role="status" id="pbStatus"></div></div>`}
function renderBeheerRest(site){
  {const off=site&&!state.canWrite;[...$("p-beheer").children].forEach(c=>{if(c.id!=="writeNote"&&c.id!=="mineCard"&&!c.classList.contains("subtabs-slot"))c.style.display=off?"none":""})}
  const mine=site&&state.canWrite&&state.meId?state.horses.filter(h=>h.eigenaar_id!=null&&String(h.eigenaar_id)===state.meId).sort((a,b)=>String(a.naam).localeCompare(String(b.naam))):null;
  $("mineCard").hidden=!mine;
  if(mine){$("mineTitle").textContent=`Mijn paarden (${mine.length})`;
    $("mineList").innerHTML=mine.length?mine.map(h=>`<div class="mine-item"><span><b>${esc(h.naam)}</b> <span class="small muted">${esc(h.geslacht||"")}${h.geboortejaar?" · "+esc(h.geboortejaar):""}</span></span><span class="row" style="gap:6px"><button class="btn ghost" type="button" data-mine="bekijk" data-id="${esc(h.id)}">Bekijk</button><button class="btn ghost" type="button" data-mine="edit" data-id="${esc(h.id)}">Bewerken</button></span></div>`).join(""):'<p class="small muted" style="margin:0">Je hebt nog geen paarden toegevoegd. Gebruik het formulier hieronder.</p>'}}
function editHorse(h){resetForm();fillForm(h);state.editId=h.id;$("formTitle").textContent="Bewerk "+h.naam;$("saveBtn").textContent="Wijzigingen opslaan";setTab("beheer");$("h-naam").focus()}
function parseLines(txt,fields){return txt.split("\n").map(l=>l.trim()).filter(Boolean).map(l=>{const p=l.split("|").map(x=>x.trim());const o={};fields.forEach((f,i)=>{o[f]=p[i]==null?"":p[i]});return o})}
function formToHorse(){const g=(id)=>$(id).value.trim();const n=(id)=>num($(id).value);
  const stamboom={};PED_KEYS.forEach(k=>{const v=g("ped-"+k);if(v)stamboom[k]=v});
  const fok=parseLines($("h-fok").value,["systeem","waarde","gemiddelde","sd","jaar","betrouwbaarheid"]).map(f=>({systeem:f.systeem,waarde:num(f.waarde),gemiddelde:num(f.gemiddelde),sd:num(f.sd),jaar:num(f.jaar),betrouwbaarheid:num(f.betrouwbaarheid)}));
  const bronnen=parseLines($("h-bronnen").value,["naam","url","datum"]);
  const h={naam:g("h-naam"),geslacht:g("h-geslacht"),geboortejaar:n("h-jaar"),stamboek:g("h-stamboek"),ueln:g("h-ueln").toUpperCase().replace(/\s/g,""),fei_id:g("h-fei"),stokmaat_cm:n("h-stokmaat"),
    stamboom,hoogste_niveau_cm:n("h-niveau"),niveau_label:g("h-niveaulabel"),nakomelingen:{sport:n("h-sport"),m140:n("h-m140"),m150:n("h-m150")},
    fokwaarden:fok,wffs:g("h-wffs"),ocd:g("h-ocd"),ocd_toelichting:g("h-ocdnote"),bronnen,opmerking:g("h-opm"),bijgewerkt:new Date().toISOString().slice(0,10)};
  if(h.geslacht==="hengst"){const d=readDekForm("h"),old=state.editId&&byId(state.editId),od=old&&old.dek;
    // Onveranderde dekinfo blijft zoals ze was (ook "automatisch opgezocht" en de bron); gewijzigde dekinfo geldt als zelf ingevuld.
    if(od&&dekGelijk(od,d))h.dek=od;else if(!dekLeeg(d)){d.bijgewerkt=h.bijgewerkt;h.dek=d}}
  return h}
function validate(h){const e=[];if(!h.naam)e.push("vul een naam in");if(h.geslacht!=="hengst"&&h.geslacht!=="merrie")e.push("kies hengst of merrie");
  if(h.ueln&&h.ueln.length!==15)e.push("een UELN heeft 15 tekens");if(!(h.bronnen||[]).some(b=>b&&b.naam))e.push("voeg minstens één bron toe");if(h.dek&&h.dek.url&&!okUrl(h.dek.url))e.push("de link naar het station begint met http:// of https://");
  (h.fokwaarden||[]).forEach(f=>{if(!f.systeem||f.waarde==null||f.gemiddelde==null||!f.sd)e.push(`fokwaarde "${f.systeem||"?"}" mist waarde, gemiddelde of standaarddeviatie`)});return e}
function docIdFor(h){return h.ueln?slug(h.ueln):slug(h.naam+"-"+(h.geboortejaar||""))}
function clean(o){return JSON.parse(JSON.stringify(o,(k,v)=>v===undefined?undefined:v))}
async function saveHorse(h,id){await db.collection(DB_COLL).doc(id).set(clean(h))}
function fillForm(h){const s=(id,v)=>{$(id).value=v==null?"":v};s("h-naam",h.naam);s("h-geslacht",h.geslacht||"hengst");s("h-jaar",h.geboortejaar);s("h-stamboek",h.stamboek);s("h-ueln",h.ueln);s("h-fei",h.fei_id);s("h-stokmaat",h.stokmaat_cm);
  PED_KEYS.forEach(k=>s("ped-"+k,h.stamboom&&h.stamboom[k]));s("h-niveau",h.hoogste_niveau_cm);s("h-niveaulabel",h.niveau_label);const o=h.nakomelingen||{};s("h-sport",o.sport);s("h-m140",o.m140);s("h-m150",o.m150);
  s("h-fok",(h.fokwaarden||[]).map(f=>[f.systeem,f.waarde,f.gemiddelde,f.sd,f.jaar,f.betrouwbaarheid].map(x=>x==null?"":x).join(" | ")).join("\n"));
  s("h-wffs",h.wffs||"onbekend");s("h-ocd",h.ocd||"onbekend");s("h-ocdnote",h.ocd_toelichting);s("h-bronnen",(h.bronnen||[]).map(b=>[b.naam,b.url,b.datum].map(x=>x||"").join(" | ")).join("\n"));s("h-opm",h.opmerking);setDekForm("h",h.dek||{});dekFsShow()}
