$("bkFile").addEventListener("change",async e=>{const f=e.target.files&&e.target.files[0];const st=$("bkStatus");e.target.value="";if(!f)return;
  if(!db||!state.canWrite){st.className="status err";st.textContent="Je kunt in deze weergave niets bewaren.";return}
  let data;try{data=JSON.parse(await f.text())}catch(_){st.className="status err";st.textContent="Dit is geen geldig JSON-bestand.";return}
  const cols=data&&data.formaat==="fokwijzer-export"&&data.collecties;if(!cols){st.className="status err";st.textContent="Dit is geen Fokwijzer-export.";return}
  const jobs=[];Object.keys(cols).forEach(c=>{if(!BK_COLLS.includes(c))return;Object.entries(cols[c]||{}).forEach(([id,d])=>{if(d&&typeof d==="object")jobs.push([c,id,d])})});
  if(!jobs.length){st.className="status err";st.textContent="Het bestand bevat geen gegevens.";return}
  const lab=BK_COLLS.map(c=>c+": "+Object.keys(cols[c]||{}).length).join(", ");
  st.className="status";st.innerHTML="";const q=document.createElement("span");q.textContent="Importeer "+jobs.length+" documenten ("+lab+")? Bestaande documenten met hetzelfde id worden overschreven. ";
  const ok=document.createElement("button");ok.type="button";ok.className="btn";ok.textContent="Ja, importeren";const no=document.createElement("button");no.type="button";no.className="btn ghost";no.textContent="Annuleren";no.style.marginLeft="8px";
  st.append(q,ok,no);const go=await new Promise(r=>{ok.onclick=()=>r(true);no.onclick=()=>r(false)});st.innerHTML="";if(!go){st.textContent="Import geannuleerd.";return}
  let done=0,fail=0;st.className="status";st.textContent="Importeren... 0 klaar";
  const worker=async()=>{while(jobs.length){const [c,id,d]=jobs.shift();try{await db.collection(bkPath(c)).doc(id).set(d)}catch(_){fail++}done++;if(done%25===0)st.textContent="Importeren... "+done+" klaar"}};
  await Promise.all(Array.from({length:6},worker));
  st.className=fail?"status err":"status ok";st.textContent="Import klaar: "+(done-fail)+" documenten bewaard"+(fail?", "+fail+" mislukt (probeer opnieuw te importeren)":"")+"."});
